-- =====================================================================================
-- DICCIONARIO DE DATOS DENTRO DE SUPABASE (usuario, 2026-11-05)
-- «Las descripciones, en Supabase: es donde n8n hará el trabajo.» Cada tabla, cada columna
-- y cada función que se puede llamar lleva su descripción como comentario de la base de
-- datos (se ve en el editor de tablas de Supabase). Columnas, con el formato de la hoja de
-- validaciones del usuario:
--     formato | rango | lista | obligatorio / opcional / automático | descripción + ejemplos
-- Para leerlo desde n8n, un agente de IA o el editor SQL:
--     select * from diccionario_datos() where tabla = 'envios';
--     select * from funciones_api() where grupo = 'Precio y pago';
--     select guia_automatizaciones();
-- La prueba 130 falla si una tabla, columna o función que se puede llamar se queda sin
-- descripción: las migraciones nuevas tienen que traer sus `comment on`.
-- =====================================================================================

-- ---- Lectura del diccionario -----------------------------------------------------------
create or replace function diccionario_datos()
returns table (tabla text, orden int, columna text, tipo text, no_nulo boolean, descripcion text, tabla_descripcion text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (ve_todo() or es_servidor()) then raise exception 'Solo Dynamo.' using errcode = '42501'; end if;
  return query
  select c.relname::text, a.attnum::int, a.attname::text, format_type(a.atttypid, a.atttypmod), a.attnotnull,
         col_description(c.oid, a.attnum), obj_description(c.oid, 'pg_class')
    from pg_class c join pg_attribute a on a.attrelid = c.oid
   where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and a.attnum > 0 and not a.attisdropped
   order by c.relname, a.attnum;
end $$;
revoke execute on function diccionario_datos() from public, anon;
grant execute on function diccionario_datos() to authenticated;

create or replace function funciones_api()
returns table (grupo text, funcion text, argumentos text, devuelve text, descripcion text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (ve_todo() or es_servidor()) then raise exception 'Solo Dynamo.' using errcode = '42501'; end if;
  return query
  select coalesce(substring(obj_description(p.oid, 'pg_proc') from '^\[([^\]]+)\]'), 'Sin grupo'), p.proname::text,
         pg_get_function_identity_arguments(p.oid), pg_get_function_result(p.oid), obj_description(p.oid, 'pg_proc')
    from pg_proc p
   where p.pronamespace = 'public'::regnamespace and p.prorettype <> 'trigger'::regtype
     and has_function_privilege('authenticated', p.oid, 'execute')
   order by 1, 2;
end $$;
revoke execute on function funciones_api() from public, anon;
grant execute on function funciones_api() to authenticated;

create or replace function guia_automatizaciones()
returns text language plpgsql stable security definer set search_path = public as $$
begin
  if not (ve_todo() or es_servidor()) then raise exception 'Solo Dynamo.' using errcode = '42501'; end if;
  return $guia$
GUÍA PARA AUTOMATIZACIONES (n8n, agentes de IA) — Plataforma Dynamo

1. CÓMO ENTRAR
   · Crear un usuario de Dynamo propio para las automatizaciones (p. ej. «Automatizaciones n8n», rol EMPLEADO; si solo
     va a leer, rol EMPLEADO_LECTURA). n8n inicia sesión con ese email y contraseña (Supabase Auth) y llama a la API con
     ese token. Así se aplican las mismas reglas que en la web y la auditoría dice «lo hizo n8n».
   · La clave de servicio (service_role) se salta TODAS las reglas por fila: solo para tareas de sistema que la piden
     (las marcadas «servidor» en funciones_api) y nunca en un flujo que hable con terceros. Muchas funciones de Dynamo
     solo comprueban «usuario de Dynamo» y con la clave de servicio responden «Solo Dynamo»: para esas, el usuario propio.
   · Nada de claves en los flujos a la vista: credenciales guardadas en n8n.

2. ESCRIBIR SIEMPRE CON LAS FUNCIONES, NO EN LAS TABLAS
   · Las funciones (POST /rest/v1/rpc/<funcion>) aplican las reglas del negocio: previo pago, cobertura de países,
     revisión del precio, cortes de cancelación, festivos… Escribir directamente en una tabla se las salta o lo bloquea un
     disparador. Lista y uso: select * from funciones_api();
   · Ejemplos: crear un envío de Dynamo → crear_envio; petición de un cliente → crear_solicitud_envio; poner precio a una
     solicitud → proponer_precio_solicitud; ofertar a un transportista → ofertar_envio; revisar el precio de un envío
     lejano → revisar_precio_envio; marcar una transferencia → marcar_pago_envio; horario de un sitio un día →
     horario_del_dia; ¿hay cobertura? → comprobar_cobertura.

3. LEER
   · Qué significa cada dato: select * from diccionario_datos() where tabla = 'envios';
   · Las columnas «automático» las pone la base de datos: no se escriben nunca.

4. CONVENCIONES
   · Importes en euros SIN IVA salvo que la descripción diga otra cosa (el IVA va aparte: iva_aplicado / clientes).
   · date = día (hora de Madrid); timestamptz = instante, se envía y se recibe en ISO 8601 con zona.
   · Países en código ISO de 2 letras (ES, PT, FR…). Códigos postales como texto (conservan el 0 inicial).
   · Referencia del envío (envios.referencia_gx): la pone la base de datos, GX + número, +7 entre una y la siguiente
     (la primera, GX100888689). Es la «referencia_gx_carga» de las hojas de n8n.
   · Nunca se borra el histórico: los envíos se cancelan, no se borran.

5. DATOS PERSONALES
   · Teléfonos, DNI, emails y firmas son datos personales (RGPD): no enviarlos a servicios externos (IA incluida) si no
     hace falta para la tarea, y nunca a una bolsa de cargas pública.
$guia$;
end $$;
revoke execute on function guia_automatizaciones() from public, anon;
grant execute on function guia_automatizaciones() to authenticated;

comment on function public.diccionario_datos() is '[Sistema y tareas automáticas] Diccionario de datos: cada columna de cada tabla con su tipo y su descripción (formato | rango | lista | obligatorio | descripción + ejemplos). Quién: Dynamo y servidor.';
comment on function public.funciones_api() is '[Sistema y tareas automáticas] Las funciones que se pueden llamar por la API, agrupadas, con qué hacen, quién puede y sus argumentos. Quién: Dynamo y servidor.';
comment on function public.guia_automatizaciones() is '[Sistema y tareas automáticas] Guía para n8n y agentes de IA: cómo entrar, escribir siempre con funciones, convenciones (importes sin IVA, fechas, referencia GX) y datos personales. Quién: Dynamo y servidor.';

-- ---- Descripciones (generadas a partir de la revisión de cada columna) ------------------
comment on table public.almacenamientos is 'Servicios de almacenaje de corta estancia (1-7 días) en un almacén de Dynamo, con reparto urbano opcional posterior. Se escribe directamente; si lo pide un cliente, la base de datos calcula precio, IVA y pago por adelantado (precios: tarifa_almacen() / almacenes_dynamo_tarifa()).';
comment on column public.almacenamientos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del almacenamiento.';
comment on column public.almacenamientos.codigo is 'formato: texto | rango: patrón AX + 6 cifras | lista: no aplica | automático | Código legible: AX más 6 cifras correlativas. Lo pone la base de datos. Ej. OK: AX100245 · Ej. mal: AX-12';
comment on column public.almacenamientos.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | obligatorio | Cliente que contrata el almacenamiento (→ clientes.id). Si lo pide el propio cliente, lo pone la base de datos y no se puede cambiar.';
comment on column public.almacenamientos.almacen_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | obligatorio | Almacén de Dynamo donde se guarda (→ lugares.id con es_almacen_dynamo, no borrado). Si está Completo no admite altas nuevas.';
comment on column public.almacenamientos.fecha_entrada is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | obligatorio | Día en que entra la mercancía (date). Ej. OK: 2026-11-10';
comment on column public.almacenamientos.fecha_salida is 'formato: fecha (AAAA-MM-DD) | rango: >= fecha_entrada | lista: no aplica | obligatorio | Día en que sale (date), no anterior a la entrada. El servicio es de 1 a 7 días, pero no se bloquea: alargarlo es un caso real (la app avisa y se cobra cada semana empezada). Ej. OK: 2026-11-14 · Ej. mal: 2026-11-09 con entrada el 10';
comment on column public.almacenamientos.num_trailers is 'formato: número entero | rango: 1 a 10 | lista: no aplica | obligatorio | Número de tráileres completos que se almacenan (cada uno se cobra por semana). Ej. OK: 2 · Ej. mal: 0';
comment on column public.almacenamientos.descripcion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Qué se almacena, en texto libre. Ej. OK: 20 palets de material eléctrico';
comment on column public.almacenamientos.referencia_cliente is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Referencia propia del cliente (su nº de pedido) para identificar el servicio. Ej. OK: PED-0000';
comment on column public.almacenamientos.num_repartos is 'formato: número entero | rango: 0 a 20 | lista: no aplica | obligatorio | Repartos urbanos posteriores desde el almacén (0 = recoge el cliente). Si es mayor que 0, hace falta lugar_entrega_id. Ej. OK: 3 · Ej. mal: 25';
comment on column public.almacenamientos.lugar_entrega_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | opcional | Sitio de entrega de los repartos (→ lugares.id, del mismo cliente o almacén Dynamo). Obligatorio si num_repartos > 0 y vacío si es 0.';
comment on column public.almacenamientos.distancia_entrega_km is 'formato: número decimal (2 decimales) | rango: máx. 20 | lista: no aplica | opcional | Km del almacén al sitio de entrega, medidos por la app con Google. El reparto urbano llega como máximo a 20 km. Ej. OK: 12.50 · Ej. mal: 35';
comment on column public.almacenamientos.importe_almacenaje is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Importe del almacenaje en euros sin IVA, congelado al crear: tráileres × semanas × precio semanal. Si lo pide un cliente lo calcula la base de datos; si no, lo pone Dynamo. Ej. OK: 480.00 · Ej. mal: -10';
comment on column public.almacenamientos.importe_reparto is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Importe de los repartos en euros sin IVA, congelado al crear: repartos × precio por reparto. Si lo pide un cliente lo calcula la base de datos. Ej. OK: 660.00';
comment on column public.almacenamientos.importe_total is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Total en euros sin IVA = almacenaje + reparto. Columna calculada por la base de datos: no se escribe.';
comment on column public.almacenamientos.iva_aplicado is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | Porcentaje de IVA aplicado (21 = 21 %). Si lo pide un cliente, sale de su ficha (por defecto 21). Ej. OK: 21.00 · Ej. mal: 0.21';
comment on column public.almacenamientos.pago_adelantado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si se paga por adelantado con proforma (cliente sin crédito). Si lo pide un cliente, lo decide la base de datos según su crédito.';
comment on column public.almacenamientos.estado is 'formato: lista cerrada (estado_almacenamiento) | rango: no aplica | lista: pendiente_confirmar, confirmado, en_almacen, finalizado, cancelado | opcional | Situación del almacenamiento. Nace pendiente de confirmar; los siguientes pasos los marca Dynamo (el cliente solo puede cancelarlo antes de la confirmación).';
comment on column public.almacenamientos.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas internas de Dynamo. La columna queda siempre vacía: al escribir, un disparador mueve el texto a notas_internas (solo Dynamo; lo de un cliente se descarta).';
comment on column public.almacenamientos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.almacenamientos.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.almacenamientos.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.almacenamientos.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on column public.almacenamientos.pagado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Cuándo validó Dynamo el pago por adelantado (instante, timestamptz). Vacío = sin pagar, o no hace falta (pago_adelantado = false). Solo Dynamo.';
comment on table public.auditoria is 'Append-only. Una fila por cada alta, modificación y baja de las tablas con rastro. La escriben los disparadores fn_auditar() (y registrar_cambio_email()). Nunca se edita ni se borra (tg_auditoria_inmutable), salvo la limpieza RGPD de IPs, hoy apagada. Solo Dynamo la lee; historial_registro() da la versión legible.';
comment on column public.auditoria.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número correlativo de la entrada. Lo pone la base de datos.';
comment on column public.auditoria.tabla is 'formato: texto | rango: no aplica | lista: no aplica | automático | Nombre de la tabla en la que se hizo el cambio. Ej. OK: envios';
comment on column public.auditoria.registro_id is 'formato: texto | rango: no aplica | lista: no aplica | automático | Identificador (columna id) de la fila cambiada, guardado como texto. Ej. OK: 3f6c2a9e-1b4d-4e8a-9c7f-2d5b8e1a6c40';
comment on column public.auditoria.accion is 'formato: texto | rango: no aplica | lista: alta (fila creada), modificacion (fila cambiada), baja (fila borrada) | automático | Tipo de cambio.';
comment on column public.auditoria.quien is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Usuario que hizo el cambio (→ auth.users.id, sin clave ajena para que sobreviva a su baja). Vacío si fue una migración o un proceso interno.';
comment on column public.auditoria.quien_email is 'formato: texto | rango: no aplica | lista: no aplica | automático | Copia del email de quien hizo el cambio en ese momento. Se guarda aparte de «quien» porque un usuario puede cambiar de email o darse de baja, y el rastro tiene valor probatorio.';
comment on column public.auditoria.quien_origen is 'formato: texto | rango: no aplica | lista: app (panel o API), migracion-sheet (carga inicial desde el Sheet), n8n (previsto), sistema (previsto) | automático | Por dónde entró el cambio. Hoy solo se escriben app y migracion-sheet; n8n y sistema están previstos pero no se usan.';
comment on column public.auditoria.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se hizo el cambio (instante, hora del servidor).';
comment on column public.auditoria.cambios is 'formato: JSON | rango: no aplica | lista: no aplica | automático | En alta: {"despues": {...}}. En baja: {"antes": {...}}. En modificación: solo los campos tocados, {"campo": {"antes": x, "despues": y}}. Si es una anonimización RGPD, solo los nombres de los campos.';
comment on table public.avisos is 'Novedades de la campana del panel, para Dynamo, para un cliente (toda su empresa) o para un transportista. Las crean solo disparadores de la base de datos (vía crear_aviso()); nadie las escribe a mano. Se leen con mis_avisos() (últimos 60 días, máx. 30) y se marcan con marcar_avisos_vistos(). No se borran.';
comment on column public.avisos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del aviso.';
comment on column public.avisos.para is 'formato: texto | rango: no aplica | lista: dynamo (equipo de Dynamo), cliente (toda la empresa cliente; exige cliente_id), transportista (exige transportista_id) | automático | A quién va el aviso.';
comment on column public.avisos.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | automático | Empresa cliente destinataria (→ clientes.id). Solo si para = cliente.';
comment on column public.avisos.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | automático | Transportista destinatario (→ transportistas.id). Solo si para = transportista.';
comment on column public.avisos.tipo is 'formato: texto | rango: no aplica | lista: no aplica | automático | Qué ha pasado, en clave corta, para filtrar o elegir icono. Ej.: precio, asignado, en_ruta, entregado, cancelado, siniestro, incidencia, penalizacion, cmr_entrega. Ej. OK: entregado';
comment on column public.avisos.nivel is 'formato: texto | rango: no aplica | lista: info (informativo), ok (buena noticia), aviso (requiere atención), urgente (actuar ya) | automático | Importancia del aviso.';
comment on column public.avisos.titulo is 'formato: texto | rango: no aplica | lista: no aplica | automático | Título corto del aviso (máx. 200 caracteres), normalmente con la referencia del envío. Ej. OK: Entregado · #GX10045';
comment on column public.avisos.texto is 'formato: texto | rango: no aplica | lista: no aplica | automático | Detalle del aviso (máx. 500 caracteres). Puede estar vacío. Al cliente nunca se le pone el precio del transportista.';
comment on column public.avisos.enlace is 'formato: texto | rango: no aplica | lista: no aplica | automático | Ruta relativa del panel a la que lleva el aviso, p. ej. /panel/envios?ver=<id del envío>. Puede estar vacía.';
comment on column public.avisos.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío relacionado (→ envios.id), si lo hay. Si el envío se borra, el aviso se borra con él.';
comment on column public.avisos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se creó el aviso (instante). Sale como «nuevo» si es posterior a avisos_vistos.visto_en de quien lo mira.';
comment on table public.avisos_vistos is 'Última vez que cada persona abrió la campana de avisos (una fila por usuario), para saber qué avisos son nuevos. Va aparte de usuarios para no llenar la auditoría. Se escribe solo con marcar_avisos_vistos(); cada uno lee solo la suya.';
comment on column public.avisos_vistos.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | automático | Usuario (→ usuarios.id). Una fila por usuario.';
comment on column public.avisos_vistos.visto_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo abrió la campana por última vez (instante). Los avisos posteriores salen como nuevos.';
comment on table public.clientes is 'Empresas cliente de Dynamo: datos fiscales (Holded), condiciones de pago, crédito (CESCE) y factor de precio. Solo la escribe Dynamo (el cliente la lee con mi_empresa()). El sitio principal se pone con marcar_sitio_principal(); el factor lo ajusta solo la regla del descuento de bienvenida.';
comment on column public.clientes.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del cliente. Es el que usan las relaciones (cliente_id) de las demás tablas.';
comment on column public.clientes.codigo is 'formato: texto | rango: C- + número, desde 10000 | lista: no aplica | automático | Código legible para hablar por teléfono (C-10042). Lo pone la base de datos con una secuencia; las relaciones usan id, no este código. Ej. OK: C-10042';
comment on column public.clientes.razon_social is 'formato: texto | rango: no puede estar vacío | lista: no aplica | obligatorio | Nombre fiscal completo de la empresa. Es el «Nombre» que se exporta a Holded. Ej. OK: Transportes Ejemplo S.L. · Ej. mal: (vacío o solo espacios)';
comment on column public.clientes.cif is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | CIF/NIF fiscal. Único entre clientes (se compara sin guiones, puntos ni espacios y en mayúsculas); el mismo CIF sí puede ser además transportista. Ej. OK: B12345678 · Ej. mal: b-12345678 si ya existe B12345678';
comment on column public.clientes.direccion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Calle y número del domicilio fiscal. Se exporta a Holded. Ej. OK: Calle Mayor 12';
comment on column public.clientes.poblacion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Población del domicilio fiscal. Ej. OK: Sevilla';
comment on column public.clientes.codigo_postal is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Código postal del domicilio fiscal. Es texto a propósito para no perder el cero inicial. Ej. OK: 08185 · Ej. mal: 8185';
comment on column public.clientes.provincia is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Provincia del domicilio fiscal. Ej. OK: Barcelona';
comment on column public.clientes.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas (ISO 3166-1) | lista: no aplica | opcional | País del domicilio fiscal en código ISO de 2 letras; el nombre («España») se saca de aquí al enseñarlo. Por defecto ES. Decide la operación de Holded (nacional, UE, exportación). Ej. OK: PT · Ej. mal: es';
comment on column public.clientes.iva_porcentaje is 'formato: número decimal (2 decimales) | rango: 0 a 100 | lista: no aplica | opcional | IVA (%) de sus facturas. Se usa en la exportación a Holded si el envío no lleva el suyo, y para calcular su riesgo con IVA. Por defecto 21. Ej. OK: 21 · Ej. mal: 121';
comment on column public.clientes.retencion_porcentaje is 'formato: número decimal (2 decimales) | rango: 0 a 100 | lista: no aplica | opcional | Retención (%) que se aplica en sus facturas (normalmente 0). Se exporta a Holded si el envío no lleva la suya. Ej. OK: 0 · Ej. mal: -5';
comment on column public.clientes.recargo_equivalencia_porcentaje is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | Recargo de equivalencia (%) de sus facturas (normalmente 0). Se exporta a Holded. La base de datos no le pone límites. Ej. OK: 5.20';
comment on column public.clientes.forma_pago_holded_id is 'formato: texto | rango: no aplica | lista: no aplica | opcional | ID de la forma de pago del cliente en Holded. Se exporta tal cual en el pedido de venta. Ej. OK: 5f2a0c1e9b3d4a0012ab34cd';
comment on column public.clientes.cuenta_contable is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Cuenta contable del cliente (contabilidad / Holded). Hoy no la usa ninguna exportación. Ej. OK: 43000123';
comment on column public.clientes.moneda is 'formato: texto | longitud_fija: 3 | rango: 3 letras | lista: no aplica | opcional | Moneda del cliente en código ISO de 3 letras. Por defecto EUR. Hoy no la usa ninguna pantalla ni exportación (la moneda va en cada envío). Ej. OK: EUR · Ej. mal: €';
comment on column public.clientes.tags is 'formato: lista de text | rango: no aplica | lista: no aplica | opcional | Etiquetas libres del cliente. Salen en la exportación a Holded unidas con «-». Lista vacía por defecto. Ej. OK: {andalucia,industria}';
comment on column public.clientes.plazo_pago_dias is 'formato: número entero | rango: no aplica | lista: 0 (contado), 30, 60, 90, 120 (por defecto) | opcional | Plazo de pago CLASIFICADO ante la aseguradora de crédito (CESCE). Por defecto 120 a todos, aunque de palabra paguen a 30 o 60: si se retrasan siguen cubiertos. Ej. OK: 120 · Ej. mal: 45';
comment on column public.clientes.factor_tarifa_porcentaje is 'formato: número decimal (2 decimales) | rango: -30 a 30 | lista: no aplica | opcional | SOLO DYNAMO, el cliente nunca lo ve. % que se suma (+) o se descuenta (−) a su tarifa. Si no está fijado a mano lo lleva la regla de bienvenida. Se congela en cada envío. Ej. OK: -7 · Ej. mal: -45';
comment on column public.clientes.recargo_pago_tarde_porcentaje is 'formato: número decimal (2 decimales) | rango: 0 a 100 | lista: no aplica | opcional | Recargo (%) a aplicar si paga muy tarde. Informativo: la base de datos no lo aplica sola. Por defecto 0. Ej. OK: 2 · Ej. mal: 150';
comment on column public.clientes.permite_contraoferta is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es true, el cliente puede proponer un precio más bajo a la solicitud de envío. Solo vale si además está encendido el general (parámetro contraoferta_cliente_activa). Solo Dynamo.';
comment on column public.clientes.discrecion_comercial is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Discreción comercial por defecto de sus envíos: el conductor no revela el destino en la carga ni el origen en la entrega, y el nombre del cliente no sale en la bolsa de cargas.';
comment on column public.clientes.riesgo_cesce_euros is 'formato: número decimal (2 decimales) | rango: 0 o más | lista: no aplica | opcional | Crédito en euros que concede la aseguradora CESCE. Vacío = sin clasificar; 0 = CESCE no le da crédito. Solo Dynamo. Ej. OK: 40000 · Ej. mal: -100';
comment on column public.clientes.riesgo_cesce_plazo_dias is 'formato: número entero | rango: 0 o más | lista: no aplica | opcional | Plazo en días con el que CESCE clasifica ese crédito. Informativo (pantalla CESCE - Riesgos). Solo Dynamo. Ej. OK: 120 · Ej. mal: -30';
comment on column public.clientes.riesgo_manual_euros is 'formato: número decimal (2 decimales) | rango: 0 o más | lista: no aplica | opcional | Crédito en euros que fija Dynamo a mano. Si es distinto de 0 manda sobre el de CESCE; vacío o 0 = manda CESCE. Solo Dynamo. Ej. OK: 10000 · Ej. mal: -1';
comment on column public.clientes.tipo_camion_defecto is 'formato: lista cerrada (tipo_camion) | rango: no aplica | lista: trailer_tauliner, rigido_plataforma | opcional | Tipo de camión que se propondría por defecto en sus envíos nuevos. Hoy ninguna pantalla lo rellena ni lo usa.';
comment on column public.clientes.forma_carga_defecto is 'formato: lista cerrada (forma_carga) | rango: no aplica | lista: paletizado_lateral, no_paletizada_lateral, no_paletizada_techo | opcional | Forma de carga que se propondría por defecto en sus envíos nuevos. Hoy ninguna pantalla lo rellena ni lo usa.';
comment on column public.clientes.plataforma_elevadora_defecto is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si sus envíos llevarían por defecto camión con plataforma elevadora (trampilla). Hoy ninguna pantalla lo rellena ni lo usa.';
comment on column public.clientes.tipo_mercancia_defecto is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Tipo de mercancía que se propondría por defecto en sus envíos nuevos (texto). Hoy ninguna pantalla lo rellena ni lo usa. Ej. OK: Paletizado';
comment on column public.clientes.descripcion_mercancia_defecto is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Descripción de la mercancía que se propondría por defecto en sus envíos nuevos. Hoy ninguna pantalla lo rellena ni lo usa. Ej. OK: Palets de material cerámico';
comment on column public.clientes.urgencia_defecto_dias is 'formato: número entero | rango: 0 a 30 | lista: no aplica | opcional | Urgencia por defecto en días para sus envíos nuevos. Hoy ninguna pantalla lo rellena ni lo usa. Ej. OK: 2 · Ej. mal: 45';
comment on column public.clientes.estado is 'formato: lista cerrada (estado_cuenta) | rango: no aplica | lista: activa, suspendida, pendiente_verificacion | opcional | Estado de la empresa en su ficha (activa = validado, pendiente_verificacion, suspendida). Es una etiqueta para Dynamo: quién puede entrar lo decide el estado de cada usuario.';
comment on column public.clientes.verificado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si Dynamo ha verificado la empresa (CIF real, etc.). Hoy ninguna pantalla lo usa; previsto para la comprobación con VIES/AEAT.';
comment on column public.clientes.verificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Instante (timestamptz) en que se verificó la empresa. Hoy sin uso.';
comment on column public.clientes.verificado_nota is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Nota de la verificación (cómo y con qué se comprobó). Hoy sin uso; se rellenaría a mano y más adelante con VIES/AEAT.';
comment on column public.clientes.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas internas de Dynamo sobre el cliente. El cliente no las ve.';
comment on column public.clientes.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.clientes.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.clientes.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.clientes.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on column public.clientes.lugar_defecto_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | opcional | Sitio principal del cliente (la estrella de Sitios) → lugares.id; tiene que ser un sitio suyo. Se pone con marcar_sitio_principal() y se quita solo al borrar el sitio.';
comment on column public.clientes.exige_pin is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es true, todos los puntos de carga y descarga de sus envíos exigen que el conductor valide un PIN. También se puede activar solo por sitio (lugares.exige_pin).';
comment on column public.clientes.nombre_comercial is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Opcional: cómo se le conoce. Si está vacío se usa la razón social. Ej. OK: Ejemplo Trans';
comment on column public.clientes.nombre_visible is 'formato: texto | rango: no aplica | lista: no aplica | automático | Calculada por la base de datos: el nombre comercial si lo hay, si no la razón social. Es la de listados y buscadores.';
comment on column public.clientes.factor_fijado_a_mano is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | true = Dynamo fijó el factor a mano y la regla del descuento de bienvenida ya no lo toca. Se marca solo al cambiar el factor; ponerlo a false vuelve al automático.';
comment on column public.clientes.alta_por is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | opcional | SOLO DYNAMO: empleado que captó o dio de alta al cliente, para comisiones (→ usuarios.id, debe ser admin o empleado). Vacío = alta online.';
comment on column public.clientes.sin_pago_previo_primer_envio is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Empresa conocida: su primer envío no exige pago por adelantado. No le libra si no tiene crédito disponible. Solo Dynamo.';
comment on column public.clientes.riesgo_efectivo_euros is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Calculada: el crédito que limita al cliente, en euros. El manual de Dynamo si es distinto de 0; si no, el de CESCE. Vacío = sin clasificar.';
comment on table public.cmr_enlaces is 'Enlaces de firma del CMR digital (/cmr/<token>): quien firma no necesita cuenta. Uno vivo por envío, con caducidad y revocable. Los crean mi_enlace_cmr() (cliente o transportista del envío), enlace_cmr_publico() (transportista sin cuenta) o Dynamo directamente. Solo Dynamo lee la tabla.';
comment on column public.cmr_enlaces.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del enlace.';
comment on column public.cmr_enlaces.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío al que da acceso el enlace (→ envios.id). Solo puede haber un enlace no revocado por envío.';
comment on column public.cmr_enlaces.token is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Clave secreta del enlace (/cmr/<token>): quien la tiene ve el CMR y puede firmar. La genera la base de datos. No difundirla fuera de las personas del envío.';
comment on column public.cmr_enlaces.caduca_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Hasta cuándo vale el enlace (instante). Por defecto, 60 días tras crearlo. Si ha caducado, las funciones crean otro y revocan este.';
comment on column public.cmr_enlaces.revocado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | true si el enlace está anulado y ya no vale. Al crear uno nuevo para el mismo envío, el anterior se revoca.';
comment on column public.cmr_enlaces.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.cmr_enlaces.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.cmr_enlaces.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.cmr_enlaces.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.cmr_reservas is 'Reservas anotadas en el CMR digital antes de firmar (qué falta o está dañado): permiten reclamar al seguro y salen en la casilla 18 del PDF. Se escriben solo con anotar_reservas_cmr() desde el enlace; cada una abre sola una incidencia de siniestro crítica. Máx. 3 por casilla y 10 por envío. No se editan.';
comment on column public.cmr_reservas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la reserva.';
comment on column public.cmr_reservas.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío (→ envios.id). Lo deduce anotar_reservas_cmr() a partir del enlace de firma.';
comment on column public.cmr_reservas.parada_id is 'formato: uuid | rango: no aplica | lista: no aplica | opcional | Parada de la casilla (→ envio_paradas.id, sin clave ajena): una recogida para el remitente, una entrega para el destinatario; vacía para el transportista.';
comment on column public.cmr_reservas.rol is 'formato: texto | rango: no aplica | lista: remitente (el cargador), transportista (el conductor), destinatario | obligatorio | Casilla del CMR desde la que se anota la reserva. No se admite en una casilla ya firmada.';
comment on column public.cmr_reservas.texto is 'formato: texto | rango: 3 a 1000 caracteres (sin contar espacios de los extremos) | lista: no aplica | obligatorio | Lo que se reserva: faltas, daños, embalaje roto… Se copia también al detalle de la incidencia de siniestro. Ej. OK: Faltan 2 palets; una caja llega rota · Ej. mal: ok';
comment on column public.cmr_reservas.incidencia_id is 'formato: uuid | → incidencias.id | rango: no aplica | lista: no aplica | automático | Incidencia de siniestro que abrió esta reserva (→ incidencias.id). La pone la función.';
comment on column public.cmr_reservas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se anotó la reserva (instante). La pone la base de datos.';
comment on table public.conductores is 'Conductores (una fila por persona, vengan con el transportista que vengan). Se dan de alta solos al asignar conductor en un envío (disparador), los da el transportista con mi_conductor_guardar() / mi_flota_baja(), y Dynamo los escribe directamente.';
comment on column public.conductores.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del conductor.';
comment on column public.conductores.codigo is 'formato: texto | rango: CD- + número, desde 10000 | lista: no aplica | automático | Código legible (CD-10042). Lo pone la base de datos con una secuencia. Ej. OK: CD-10042';
comment on column public.conductores.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Con quién suele venir → transportistas.id (opcional). No lo ata: el mismo conductor puede venir con otra empresa.';
comment on column public.conductores.nombre is 'formato: texto | rango: no vacío; máx. 120 caracteres desde el panel del transportista | lista: no aplica | obligatorio | Nombre y apellidos del conductor. Ej. OK: Juan García López · Ej. mal: (vacío)';
comment on column public.conductores.documento is 'formato: texto | rango: máx. 30 caracteres desde el panel | lista: no aplica | opcional | DATO PERSONAL (RGPD): DNI, NIE o pasaporte, necesario para firmar el CMR. Único entre conductores activos. Solo se anonimiza a mano si la persona lo pide. Ej. OK: 12345678Z · Ej. mal: 12345678Z si ya hay otro conductor activo con él';
comment on column public.conductores.documento_pais is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas (ISO 3166-1) | lista: no aplica | opcional | País que emitió el documento, código ISO de 2 letras. Por defecto ES. Ej. OK: PT · Ej. mal: es';
comment on column public.conductores.telefono is 'formato: texto | rango: + opcional y de 6 a 15 cifras, sin espacios ni guiones | lista: no aplica | opcional | Teléfono del conductor. El cliente lo ve mientras el envío está en curso y deja de verlo al entregarse o cancelarse (lo impone la base de datos). Ej. OK: +34600111222 · Ej. mal: 600 11 12 22';
comment on column public.conductores.activo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | false = dado de baja (mi_flota_baja). No se borra: queda para el histórico, y su documento puede volver a darse de alta.';
comment on column public.conductores.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas libres sobre el conductor.';
comment on column public.conductores.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.conductores.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.conductores.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.conductores.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on column public.conductores.idioma is 'formato: texto | rango: 2 letras minúsculas y, si hace falta, región: es, pl, zh-CN | lista: no aplica | opcional | Idioma de los avisos y de la página de firma del CMR para este conductor. Por defecto es. Ej. OK: pl · Ej. mal: ES';
comment on table public.conexion_minutos is 'Tiempo conectado al panel: minutos por usuario y día. Lo suma latido(), que el panel llama cada 5 minutos (suma 5 como mucho cada 4 min, para que no se pueda inflar). Lo usa metricas_usuarios(). Cada uno lee lo suyo y Dynamo todo; nadie la escribe a mano.';
comment on column public.conexion_minutos.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | automático | Usuario (→ usuarios.id). Junto con «dia» identifica la fila.';
comment on column public.conexion_minutos.dia is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | automático | Día de calendario (en hora de Madrid) al que corresponden los minutos.';
comment on column public.conexion_minutos.minutos is 'formato: número entero | rango: 0 a 1440 | lista: no aplica | automático | Minutos conectados ese día (sube de 5 en 5).';
comment on column public.conexion_minutos.ultimo is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Último latido recibido (instante). Si fue hace menos de 4 minutos, el siguiente no suma.';
comment on table public.consultas_precio is 'Una fila por cada solicitud de precio de un cliente, para los límites diarios y la suspensión automática de cuentas (cada fila nueva revisa a su usuario). La rellena un disparador al crear un envío que pide precio; nadie la escribe a mano. Solo Dynamo la lee.';
comment on column public.consultas_precio.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número correlativo de la consulta. Lo pone la base de datos.';
comment on column public.consultas_precio.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | automático | Usuario que pidió el precio, es decir, quien creó el envío (→ usuarios.id).';
comment on column public.consultas_precio.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | automático | Empresa cliente que pidió el precio (→ clientes.id).';
comment on column public.consultas_precio.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío (solicitud) que originó la consulta (→ envios.id). Se vacía si se borra el envío.';
comment on column public.consultas_precio.origen is 'formato: texto | rango: no aplica | lista: solicitud (petición de precio desde el panel), tarifador (cálculo del tarifador; previsto, aún no se usa) | automático | De dónde vino la consulta.';
comment on column public.consultas_precio.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se pidió el precio (instante, hora del servidor).';
comment on table public.contactos is 'Personas de contacto (varias por dueño) de un cliente, un transportista o un sitio: exactamente uno de los tres. Un contacto no es un usuario con login. Se escribe directamente en la tabla con los permisos de cada rol; el transportista no ve ni toca los de contabilidad.';
comment on column public.contactos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del contacto.';
comment on column public.contactos.codigo is 'formato: texto | rango: CT- + número, desde 10000 | lista: no aplica | automático | Código legible (CT-10042). Lo pone la base de datos con una secuencia. Ej. OK: CT-10042';
comment on column public.contactos.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | opcional | Cliente al que pertenece → clientes.id. Hay que rellenar exactamente uno de cliente_id, transportista_id o lugar_id. Se borra con el cliente.';
comment on column public.contactos.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista al que pertenece → transportistas.id. Exactamente uno de cliente_id, transportista_id o lugar_id. Se borra con el transportista.';
comment on column public.contactos.nombre is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Nombre de la persona. Puede faltar si es un buzón genérico (tráfico, administración). Ej. OK: Ana Pérez';
comment on column public.contactos.funcion is 'formato: lista cerrada (funcion_contacto) | rango: no aplica | lista: trafico, contabilidad, conductor, general | opcional | Para qué se le contacta. El email de contabilidad del transportista no se usa para la operativa de cargas (solo el de tráfico) y el transportista no lo ve.';
comment on column public.contactos.telefono is 'formato: texto | rango: + opcional y de 6 a 15 cifras, sin espacios ni guiones | lista: no aplica | opcional | Teléfono en formato internacional sin espacios (se admiten extranjeros). Hay que poner teléfono o email, al menos uno. Ej. OK: +34600111222 · Ej. mal: 600 11 12 22';
comment on column public.contactos.email is 'formato: texto | rango: formato nombre@dominio.ext | lista: no aplica | opcional | Email de contacto. Hay que poner teléfono o email, al menos uno. Ej. OK: trafico@ejemplo.es · Ej. mal: trafico@ejemplo';
comment on column public.contactos.es_principal is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es el principal de su dueño para esa función (como mucho uno por dueño y función). El panel lo marca solo: el primero de cada función.';
comment on column public.contactos.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas libres sobre el contacto.';
comment on column public.contactos.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | opcional | Si esta persona además tiene login → usuarios.id. Hoy el panel no lo rellena.';
comment on column public.contactos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.contactos.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.contactos.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.contactos.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on column public.contactos.lugar_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | opcional | Sitio al que pertenece (la persona de esa nave) → lugares.id. Exactamente uno de cliente_id, transportista_id o lugar_id. Se borra con el sitio.';
comment on column public.contactos.idioma is 'formato: texto | rango: 2 letras minúsculas y, si hace falta, región: es, pl, zh-CN | lista: no aplica | opcional | Idioma de los mensajes automáticos a este contacto. Por defecto es. Ej. OK: pl · Ej. mal: ES';
comment on column public.contactos.recibe_avisos is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si recibe los avisos automáticos de los envíos (salida hacia la carga, entregado…). Pensado para los emails/WhatsApp; hoy ninguna función de la base de datos lo lee.';
comment on column public.contactos.cargo is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Puesto de la persona, texto libre. Ej. OK: Jefe de tráfico';
comment on table public.contraoferta_intentos is 'Propuestas de precio de un cliente rechazadas por demasiado bajas (más rebaja que el parámetro contraoferta_cliente_max_pct). Con 3 en 24 h en un envío, o 6 en todo el cliente, no se admiten más ese día. La escribe solo contraofertar_precio_solicitud(); solo Dynamo la lee.';
comment on column public.contraoferta_intentos.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número correlativo. Lo pone la base de datos.';
comment on column public.contraoferta_intentos.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío sobre el que se hizo la propuesta (→ envios.id).';
comment on column public.contraoferta_intentos.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la propuesta (→ usuarios.id). Se vacía si se borra el usuario.';
comment on column public.contraoferta_intentos.importe is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Precio que propuso el cliente, en euros SIN IVA (redondeado a 2 decimales).';
comment on column public.contraoferta_intentos.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se hizo la propuesta (instante).';
comment on table public.distancias_cp is 'Caché de km entre dos códigos postales (dirigida), para el tarifador público donde no hay ficha de sitio. Los CP se comparan normalizados (sin espacios ni guiones). Solo la escribe el servidor con fn_guardar_km_cp(); se lee con fn_km_cp().';
comment on column public.distancias_cp.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la fila.';
comment on column public.distancias_cp.pais_origen is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | Código ISO de 2 letras del país de origen. Ej. OK: ES · Ej. mal: Es';
comment on column public.distancias_cp.codigo_postal_origen is 'formato: texto | rango: 3 a 10 letras/cifras sin contar separadores | lista: no aplica | obligatorio | CP de origen, como texto. Se compara normalizado: ''2400-016'' y ''2400016'' son el mismo. Ej. OK: 41001 · Ej. mal: 41';
comment on column public.distancias_cp.pais_destino is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | Código ISO de 2 letras del país de destino. Ej. OK: PT';
comment on column public.distancias_cp.codigo_postal_destino is 'formato: texto | rango: 3 a 10 letras/cifras sin contar separadores | lista: no aplica | obligatorio | CP de destino, como texto. Se compara normalizado. Ej. OK: 2400-016 · Ej. mal: 2';
comment on column public.distancias_cp.km is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | obligatorio | Kilómetros por carretera entre los dos CP, según el proveedor de mapas. Ej. OK: 455.00 · Ej. mal: -3';
comment on column public.distancias_cp.minutos is 'formato: número entero | rango: >= 0 | lista: no aplica | opcional | Duración estimada en minutos, según el proveedor de mapas. Ej. OK: 290';
comment on column public.distancias_cp.proveedor is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Servicio de mapas que dio los km. Ej. OK: google_routes';
comment on column public.distancias_cp.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.distancias_cp.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.distancias_cp.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.distancias_cp.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on table public.distancias_lugares is 'Caché de km de Google entre dos sitios de la agenda (pareja dirigida A→B + version_geo de cada extremo): al mudarse un sitio la fila vieja deja de valer sola. Las viejas no se borran: justifican con qué km se tarificó cada envío. Solo la escribe el servidor con fn_guardar_km_lugares(); se lee con fn_km_lugares().';
comment on column public.distancias_lugares.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la fila.';
comment on column public.distancias_lugares.lugar_origen_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | obligatorio | Sitio de salida del tramo (→ lugares.id). A→B y B→A se guardan aparte.';
comment on column public.distancias_lugares.version_origen is 'formato: número entero | rango: no aplica | lista: no aplica | automático | version_geo del sitio de origen cuando se pidieron los km. La pone fn_guardar_km_lugares() leyendo la actual.';
comment on column public.distancias_lugares.lugar_destino_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | obligatorio | Sitio de llegada del tramo (→ lugares.id); distinto del origen.';
comment on column public.distancias_lugares.version_destino is 'formato: número entero | rango: no aplica | lista: no aplica | automático | version_geo del sitio de destino cuando se pidieron los km. La pone fn_guardar_km_lugares().';
comment on column public.distancias_lugares.km is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | obligatorio | Kilómetros por carretera del tramo, según el proveedor de mapas. Ej. OK: 534.20 · Ej. mal: -1';
comment on column public.distancias_lugares.minutos is 'formato: número entero | rango: >= 0 | lista: no aplica | opcional | Duración estimada del tramo en minutos, según el proveedor de mapas. Ej. OK: 320';
comment on column public.distancias_lugares.proveedor is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Servicio de mapas que dio los km. Ej. OK: google_routes';
comment on column public.distancias_lugares.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.distancias_lugares.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.distancias_lugares.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.distancias_lugares.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on table public.documentos is 'Ficha de cada fichero subido (albaranes, CMR, fotos, documentación de transportistas, logos, recursos): el fichero vive en el almacén privado de Supabase Storage y aquí van sus datos y a qué pertenece. Se inserta directamente tras subir el fichero; nunca se borra (borrado suave).';
comment on column public.documentos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del documento.';
comment on column public.documentos.tipo is 'formato: texto | rango: no aplica | lista: albaran, cmr, cmr_firmado, orden_transporte, proforma, seguro_cmr (seguro del transportista), tarjeta_transporte, foto_incidencia, gps_tacografo (prueba GPS/tacógrafo del viaje), hoja_cif, dni, logo (de un operador), adjunto, otro | obligatorio | Clase de documento. Ej. OK: albaran · Ej. mal: factura';
comment on column public.documentos.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | opcional | Envío al que pertenece (→ envios.id). Un documento cuelga al menos de una cosa (o es un recurso) y puede colgar de varias.';
comment on column public.documentos.incidencia_id is 'formato: uuid | → incidencias.id | rango: no aplica | lista: no aplica | opcional | Incidencia a la que pertenece (→ incidencias.id), p. ej. una foto de daños.';
comment on column public.documentos.almacenamiento_id is 'formato: uuid | → almacenamientos.id | rango: no aplica | lista: no aplica | opcional | Almacenamiento al que pertenece (→ almacenamientos.id), p. ej. su proforma.';
comment on column public.documentos.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista al que pertenece (→ transportistas.id): documentación de su ficha (máx. 5 sin envío) o de sus viajes.';
comment on column public.documentos.storage_bucket is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Carpeta raíz (bucket) de Supabase Storage donde está el fichero. Siempre el privado ''documentos''. Ej. OK: documentos';
comment on column public.documentos.storage_ruta is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Ruta del fichero dentro del bucket. Quien no es Dynamo solo sube a su carpeta u/<su id de usuario>/. Única por bucket. Ej. OK: u/<id-usuario>/albaran-ejemplo.pdf · Ej. mal: ruta repetida de otro documento';
comment on column public.documentos.nombre_archivo is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre del fichero tal como se enseña o se descarga. Ej. OK: albaran-ejemplo.pdf';
comment on column public.documentos.tipo_mime is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Tipo de fichero. El almacén solo admite PDF e imágenes (JPEG, PNG, WEBP, HEIC/HEIF). Ej. OK: application/pdf · Ej. mal: application/zip';
comment on column public.documentos.tamano_bytes is 'formato: número entero | rango: 0 a 26214400 (25 MB) | lista: no aplica | opcional | Tamaño del fichero en bytes. Ej. OK: 184320 · Ej. mal: 30000000';
comment on column public.documentos.sha256 is 'formato: texto | rango: 64 caracteres hexadecimales en minúscula | lista: no aplica | opcional | Huella SHA-256 del fichero, para probar que no se ha cambiado después. Ej. OK: (64 caracteres 0-9a-f) · Ej. mal: ABC123';
comment on column public.documentos.visible_cliente is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si lo ve el cliente del envío, incidencia o almacenamiento (albarán y CMR sí; seguro o tarjeta del transportista no). Solo Dynamo lo marca: lo que sube otro queda en falso.';
comment on column public.documentos.borrado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Borrado SUAVE: el documento deja de verse, pero la fila y el fichero se conservan (tienen valor de prueba).';
comment on column public.documentos.borrado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Cuándo se marcó como borrado (instante, timestamptz). Hay que rellenarla a la vez que borrado = true (y vaciarla si se recupera).';
comment on column public.documentos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.documentos.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.documentos.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.documentos.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on column public.documentos.penalizacion_id is 'formato: uuid | → penalizaciones.id | rango: no aplica | lista: no aplica | opcional | Penalización a la que pertenece (→ penalizaciones.id), p. ej. un justificante.';
comment on column public.documentos.operador_id is 'formato: uuid | → operadores.id | rango: no aplica | lista: no aplica | opcional | Operador al que pertenece (→ operadores.id): su logo, que sale en la orden de transporte.';
comment on column public.documentos.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | opcional | Usuario al que pertenece (→ usuarios.id): documentación de su alta (hoja de CIF, DNI…).';
comment on column public.documentos.es_recurso is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Documento de la pantalla Recursos (condiciones, guías, certificados): lo ve cualquier cuenta activa y no cuelga de nada más. Solo Dynamo lo publica.';
comment on column public.documentos.recurso_titulo is 'formato: texto | rango: 1 a 120 caracteres | lista: no aplica | opcional | Título del recurso. Obligatorio si es_recurso. Ej. OK: Condiciones generales de transporte';
comment on column public.documentos.recurso_descripcion is 'formato: texto | rango: máx. 300 caracteres | lista: no aplica | opcional | Línea de descripción del recurso. Ej. OK: Versión vigente desde enero.';
comment on table public.envio_hitos is 'Historial append-only de cada envío: cada momento (creado, confirmado, ofertado, cargado, entregado, PIN, cambios de ruta…) con la hora del SERVIDOR. Nunca se cambia ni se borra. Lo escriben solo los disparadores de envios y las funciones (registrar_hito, interna).';
comment on column public.envio_hitos.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Identificador correlativo del hito.';
comment on column public.envio_hitos.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío al que pertenece el hito (→ envios.id).';
comment on column public.envio_hitos.hito is 'formato: lista cerrada (tipo_hito) | rango: no aplica | lista: creado, confirmado, publicado_bolsa, transportista_asignado, transportista_quitado, matricula_asignada, cargado, entregado, cancelado, cancelacion_deshecha, ofertado, enlace_abierto, reservado, reserva_caducada, reserva_liberada, contraoferta_propuesta, contraoferta_resuelta, orden_transporte_enviada, cmr_firmado, pin_enviado, pin_validado, pin_validado_manual, pin_fuera_de_orden, pin_bloqueado, incidencia, ruta_cambiada | obligatorio | Qué pasó (creado, confirmado, transportista_asignado, cargado, entregado, cancelado, ofertado, reservado, pin_validado, ruta_cambiada…). Cliente y transportista solo ven algunos.';
comment on column public.envio_hitos.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo pasó (instante, hora del SERVIDOR). La pone un disparador; solo al migrar el Sheet se conserva la original.';
comment on column public.envio_hitos.quien is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Usuario que lo provocó (auth.users.id, sin clave ajena). Vacío = sistema o persona sin cuenta. Lo pone un disparador.';
comment on column public.envio_hitos.quien_origen is 'formato: texto | rango: no aplica | lista: app (desde la plataforma), servidor (servidor o página pública), sistema (procesos automáticos), migracion-sheet (importado del Sheet) | automático | De dónde vino el hito.';
comment on column public.envio_hitos.parada_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Parada a la que se refiere, si aplica (id de envio_paradas, sin clave ajena: la parada puede borrarse).';
comment on column public.envio_hitos.oferta_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Oferta a la que se refiere, si aplica (id de envio_ofertas).';
comment on column public.envio_hitos.datos is 'formato: JSON | rango: no aplica | lista: no aplica | automático | Detalles del hito en JSON (precio, transportista, estado anterior, ruta antes/después, motivo de cancelación…). {} si no hay.';
comment on table public.envio_ofertas is 'Ofertas de una carga a transportistas: una fila por transportista y envío (y una sin transportista para la bolsa), con su enlace y precio. No se borra: es el histórico. Se crea con ofertar_envio() (solo Dynamo o servidor); la aceptación la cierran las funciones de reserva.';
comment on column public.envio_ofertas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la oferta.';
comment on column public.envio_ofertas.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío ofertado (→ envios.id).';
comment on column public.envio_ofertas.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista al que se oferta (→ transportistas.id). Vacío solo en canales de bolsa: se identifica al aceptar.';
comment on column public.envio_ofertas.canal is 'formato: texto | rango: no aplica | lista: email, whatsapp, telefono, bolsa_wtransnet, bolsa_teleroute, bolsa_otra, panel (panel del transportista) | obligatorio | Por dónde se ofertó. Ej. OK: email · Ej. mal: sms';
comment on column public.envio_ofertas.token is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Enlace personal aleatorio de la oferta (no se puede deducir de nada). Lo pone la base de datos.';
comment on column public.envio_ofertas.precio_ofertado is 'formato: número decimal (2 decimales) | rango: mayor que 0 | lista: no aplica | obligatorio | Precio ofrecido al transportista, en euros SIN IVA. Ej. OK: 700.00 · Ej. mal: 0';
comment on column public.envio_ofertas.banda_pct is 'formato: número entero | rango: no aplica | lista: 0 (precio fijo), 5, 10, 30 | obligatorio | SOLO DYNAMO: banda de negociación en %. El transportista ve el rango en euros (banda_euros), nunca el porcentaje.';
comment on column public.envio_ofertas.banda_euros is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Margen de negociación en euros: % de banda_pct sobre el precio, redondeado a 10 € y mínimo 10 € (0 si precio fijo). Columna generada.';
comment on column public.envio_ofertas.pronto_pago is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | La oferta permite pronto pago. Se quita solo si la línea de pronto pago está apagada o agotada o el transportista no lo tiene.';
comment on column public.envio_ofertas.estado is 'formato: texto | rango: no aplica | lista: activa, aceptada (este la ganó), cerrada (la ganó otro), caducada, revocada | automático | Situación de la oferta. La fila NO se borra. La caducidad real se mira con caduca_en; ninguna función pone hoy caducada ni revocada.';
comment on column public.envio_ofertas.enviada_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se envió la oferta (instante). La pone la base de datos.';
comment on column public.envio_ofertas.caduca_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Hasta cuándo vale el enlace (instante). ofertar_envio() lo pone a 7 días (oferta_dias_caducidad).';
comment on column public.envio_ofertas.abierta_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Primera vez que el transportista abrió el enlace (instante). Lo pone reservar_envio().';
comment on column public.envio_ofertas.aperturas is 'formato: número entero | rango: >= 0 | lista: no aplica | automático | Veces que se ha abierto el enlace. Lo suma reservar_envio().';
comment on column public.envio_ofertas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de creación de la fila (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_ofertas.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos (auditoría); vacío si lo creó un proceso.';
comment on column public.envio_ofertas.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_ofertas.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos (auditoría).';
comment on table public.envio_parada_pines is 'El PIN de cada punto de la ruta. SOLO DYNAMO la lee: el conductor manda un número a validar_pin_parada() y el servidor compara. Los crea preparar_pines_envio() al confirmar el envío si el cliente o el sitio exige PIN; se gestionan con regenerar_pin_parada(), marcar_pin_enviado() y validar_pin_manual().';
comment on column public.envio_parada_pines.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la fila.';
comment on column public.envio_parada_pines.parada_id is 'formato: uuid | → envio_paradas.id | rango: no aplica | lista: no aplica | automático | Punto de la ruta al que pertenece el PIN (→ envio_paradas.id). Uno por parada.';
comment on column public.envio_parada_pines.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío de la parada (→ envios.id).';
comment on column public.envio_parada_pines.pin is 'formato: texto | rango: 4 a 8 cifras | lista: no aplica | automático | Código numérico que el muelle da al conductor. Se genera al azar con las cifras del parámetro pin_cifras (hoy 4). Secreto: solo sale para mandarlo al contacto del muelle. Ej. OK: 4821 · Ej. mal: 48A1';
comment on column public.envio_parada_pines.exigido is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | Si el punto exige validar el PIN. Hoy siempre true: ninguna función lo pone a false y regenerar el PIN lo vuelve a poner a true.';
comment on column public.envio_parada_pines.enviado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se mandó el PIN al contacto del muelle (instante). Lo pone marcar_pin_enviado(); se vacía al regenerar el PIN.';
comment on column public.envio_parada_pines.enviado_a is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Email o móvil del muelle al que se mandó el PIN (máx. 200 caracteres). Se pasa a marcar_pin_enviado(); se vacía al regenerar. Ej. OK: muelle@almacen-ejemplo.es';
comment on column public.envio_parada_pines.intentos_fallidos is 'formato: número entero | rango: no aplica | lista: no aplica | automático | PIN incorrectos acumulados. Los suma validar_pin_parada(); vuelve a 0 al regenerar el PIN.';
comment on column public.envio_parada_pines.bloqueado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | true al llegar a pin_max_intentos fallos (hoy 3): ya no se acepta ningún PIN y hay que llamar a Dynamo, que valida a mano o regenera.';
comment on column public.envio_parada_pines.validado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se validó el punto (instante, hora del servidor). Vacío = sin validar. Siempre va junto con validado_modo.';
comment on column public.envio_parada_pines.validado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario de Dynamo que lo validó a mano (→ auth.users.id). Vacío si lo validó el conductor con el PIN.';
comment on column public.envio_parada_pines.validado_modo is 'formato: texto | rango: no aplica | lista: enlace (el conductor acertó el PIN), manual_dynamo (Dynamo lo validó a mano con validar_pin_manual()) | automático | Cómo se validó el punto. Vacío mientras no está validado.';
comment on column public.envio_parada_pines.validado_nota is 'formato: texto | rango: mín. 5 caracteres si la validación es manual | lista: no aplica | opcional | Quién llamó y por qué se validó a mano. Obligatoria si el modo es manual_dynamo; se pasa a validar_pin_manual(). Ej. OK: Llamó el conductor: muelle sin cobertura · Ej. mal: ok';
comment on column public.envio_parada_pines.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.envio_parada_pines.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.envio_parada_pines.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.envio_parada_pines.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.envio_paradas is 'Una fila por punto de la ruta de un envío, cargas y descargas en UNA sola secuencia `orden`. Origen = menor orden, destino = mayor. Guarda la dirección congelada. Se escribe con crear_envio(), crear_solicitud_envio(), crear_envio_manual() y cambiar_ruta_envio(); solo Dynamo directamente.';
comment on column public.envio_paradas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la parada.';
comment on column public.envio_paradas.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío al que pertenece (→ envios.id). Si se borra el envío, se borran sus paradas.';
comment on column public.envio_paradas.orden is 'formato: número entero | rango: mayor que 0, único por envío | lista: no aplica | obligatorio | Posición en la ruta, única por envío. Puede tener huecos (renumerar_paradas() los compacta). La primera debe ser carga y la última descarga. Ej. OK: 1 · Ej. mal: 0';
comment on column public.envio_paradas.tipo is 'formato: texto | rango: no aplica | lista: carga (recogida), descarga (entrega) | obligatorio | Si en este punto se carga o se descarga. Ej. OK: carga · Ej. mal: recogida';
comment on column public.envio_paradas.lugar_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | opcional | Sitio de la agenda del cliente o almacén de Dynamo del que sale la dirección (→ lugares.id). Vacío si la dirección se escribió suelta.';
comment on column public.envio_paradas.nombre_empresa is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Empresa del punto, copia congelada del sitio el día del viaje. Ej. OK: Almacenes Ejemplo S.L.';
comment on column public.envio_paradas.direccion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Calle y número, SOLO eso (CP y población van aparte). Copia congelada. Ej. OK: Calle Mayor 12';
comment on column public.envio_paradas.codigo_postal is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Código postal. TEXTO siempre: ''08185'' como número sería 8185. Formatos de otros países admitidos. Ej. OK: 08185 · Ej. mal: 8185';
comment on column public.envio_paradas.poblacion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Población del punto. Obligatoria en paradas sueltas pedidas por el cliente o al cambiar ruta. Ej. OK: Sevilla';
comment on column public.envio_paradas.provincia is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Provincia o región del punto. Ej. OK: Sevilla';
comment on column public.envio_paradas.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | País del punto, código ISO de 2 letras en mayúsculas. Ej. OK: ES · Ej. mal: España';
comment on column public.envio_paradas.lat is 'formato: número decimal (6 decimales) | rango: -90 a 90 | lista: no aplica | opcional | Latitud (grados decimales), copiada del sitio de la agenda. Ej. OK: 37.389100 · Ej. mal: 120';
comment on column public.envio_paradas.lon is 'formato: número decimal (6 decimales) | rango: -180 a 180 | lista: no aplica | opcional | Longitud (grados decimales), copiada del sitio de la agenda. Ej. OK: -5.984500 · Ej. mal: 200';
comment on column public.envio_paradas.fecha_desde is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Inicio de la cita concreta en este punto (instante). Hoy ninguna función la rellena; solo Dynamo a mano.';
comment on column public.envio_paradas.fecha_hasta is 'formato: fecha y hora con zona (ISO 8601) | rango: >= fecha_desde | lista: no aplica | opcional | Fin de la cita en este punto (instante). Igual o posterior a fecha_desde.';
comment on column public.envio_paradas.hora_real is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Cuándo se cargó o descargó DE VERDAD en este punto (instante). Hoy ninguna función la rellena.';
comment on column public.envio_paradas.referencia is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Referencia de carga o descarga que da el cliente para este punto. Ej. OK: REC-2211';
comment on column public.envio_paradas.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Indicaciones para esta parada concreta («muelle 3», «llamar al llegar»). Ej. OK: Muelle 3, llamar al llegar';
comment on column public.envio_paradas.km_hasta_siguiente is 'formato: número decimal (2 decimales) | rango: mayor que 0 y menor que 6000 | lista: no aplica | opcional | Kilómetros desde este punto hasta el siguiente; su suma da envios.km_total. Hoy ninguna función lo rellena. Ej. OK: 531.40 · Ej. mal: 0';
comment on column public.envio_paradas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de creación de la fila (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_paradas.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos (auditoría); vacío si lo creó un proceso.';
comment on column public.envio_paradas.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_paradas.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos (auditoría).';
comment on table public.envio_reservas is 'Histórico de reservas de cada carga: el bloqueo de 3 min al abrir el enlace y su resultado (aceptada, contraoferta, caducada…). Solo una viva por envío a la vez. Se escribe SOLO con reservar_envio(), aceptar_reserva(), aceptar_oferta_publica(), resolver_contraoferta() y liberar_reserva().';
comment on column public.envio_reservas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la reserva (es la llave que guarda quien reservó).';
comment on column public.envio_reservas.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío reservado (→ envios.id).';
comment on column public.envio_reservas.oferta_id is 'formato: uuid | → envio_ofertas.id | rango: no aplica | lista: no aplica | opcional | Oferta cuyo enlace se abrió (→ envio_ofertas.id). Vacío si se abrió el enlace general del envío (token_publico).';
comment on column public.envio_reservas.desde is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo empezó la reserva (instante, hora del servidor).';
comment on column public.envio_reservas.hasta is 'formato: fecha y hora con zona (ISO 8601) | rango: posterior a desde | lista: no aplica | automático | Cuándo caduca la reserva (instante): desde + reserva_minutos (3). La cuenta atrás de la página va contra esta hora.';
comment on column public.envio_reservas.estado is 'formato: texto | rango: no aplica | lista: viva (bloqueo de 3 min), pendiente_revision (contraoferta o alta online, la revisa Dynamo; no bloquea la carga), aceptada, caducada, liberada (la soltó), rechazada | automático | Situación de la reserva. Lo cambian solo las funciones de reserva.';
comment on column public.envio_reservas.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | automático | Transportista que aceptó o propuso precio (→ transportistas.id). Vacío mientras la reserva es anónima.';
comment on column public.envio_reservas.usuario_id is 'formato: uuid | → usuarios.id | rango: no aplica | lista: no aplica | automático | Cuenta del transportista que aceptó, si lo hizo con sesión (→ usuarios.id).';
comment on column public.envio_reservas.precio_aceptado is 'formato: número decimal (2 decimales) | rango: mayor que 0 | lista: no aplica | automático | Precio final aceptado, en euros SIN IVA; se copia a envios.importe_transportista.';
comment on column public.envio_reservas.precio_propuesto is 'formato: número decimal (2 decimales) | rango: mayor que 0 | lista: no aplica | automático | Precio distinto que propuso el transportista (contraoferta), en euros SIN IVA.';
comment on column public.envio_reservas.cerrada_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo terminó la reserva (aceptada, caducada, liberada o rechazada) (instante).';
comment on column public.envio_reservas.motivo_cierre is 'formato: texto | rango: no aplica | lista: no aplica | automático | Por qué terminó, en texto («tiempo agotado», «aceptada», «contraoferta rechazada», «la carga se la ha quedado otro transportista»…).';
comment on column public.envio_reservas.ip is 'formato: dirección IP | rango: no aplica | lista: no aplica | automático | IP desde la que se reservó (antisuplantación). No pasa a la auditoría; la limpieza RGPD, si está activa, la borra a los 90 días.';
comment on column public.envio_reservas.navegador is 'formato: texto | rango: no aplica | lista: no aplica | automático | Navegador desde el que se reservó (máx. 400 caracteres). Mismo tratamiento que ip.';
comment on column public.envio_reservas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de creación de la fila (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_reservas.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos (auditoría); vacío si lo creó un proceso.';
comment on column public.envio_reservas.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envio_reservas.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos (auditoría).';
comment on column public.envio_reservas.pronto_pago is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | El transportista eligió pronto pago al aceptar (solo si la oferta lo ofrecía).';
comment on table public.envios is 'Envíos (cargas): una fila por transporte, con estado, mercancía, precios, transportista y pago. La ruta va en envio_paradas. Solo Dynamo y el servidor escriben directamente; se crean con crear_envio(), crear_solicitud_envio() o crear_envio_manual(). No se borran: se cancelan (cancelar_envio, cancelar_mi_envio).';
comment on column public.envios.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del envío.';
comment on column public.envios.referencia_gx is 'formato: texto | rango: patrón GX + 9 cifras; +7 entre una y la siguiente | lista: no aplica | automático | Referencia pública del envío (GX + 9 cifras). La pone la base de datos con la secuencia seq_gx; es correlativa, no sirve como enlace secreto. Ej. OK: GX100888696 · Ej. mal: GX12';
comment on column public.envios.token_publico is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador aleatorio del enlace público de aceptar carga (/carga/<token>). El GX no vale ahí: es correlativo de paso +7 y 1 de cada 7 números adivinaría un envío ajeno.';
comment on column public.envios.referencia_cliente is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Referencia interna del cliente para este envío (su nº de pedido). Texto libre. Ej. OK: PED-2026-0457';
comment on column public.envios.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | obligatorio | Cliente al que pertenece y se factura el envío (→ clientes.id).';
comment on column public.envios.estado is 'formato: lista cerrada (estado_envio) | rango: no aplica | lista: borrador, programado, hacia_la_carga, cargando, en_ruta, entregado, cancelado | obligatorio | Estado del envío: borrador (a medias o solicitud sin aceptar) → programado → hacia_la_carga → cargando → en_ruta → entregado; o cancelado. Al salir de borrador se exige ruta completa; los cambios dejan hito.';
comment on column public.envios.estado_asignacion is 'formato: lista cerrada (estado_asignacion) | rango: no aplica | lista: sin_asignar, ofertada, reservada, confirmada | automático | Situación del transportista: sin_asignar, ofertada (hay ofertas), reservada (alguien la tiene 3 min), confirmada. La mueven ofertar_envio(), reservar_envio() y la aceptación; ningún disparador lo hace al asignar a mano.';
comment on column public.envios.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista asignado (→ transportistas.id). Lo pone la aceptación de la carga o Dynamo a mano. Prohibido en envíos manuales, con pago pendiente o con precio provisional.';
comment on column public.envios.vehiculo_camion_id is 'formato: uuid | → vehiculos.id | rango: no aplica | lista: no aplica | automático | Camión de la flota (→ vehiculos.id) que corresponde a matricula_camion. Lo pone un disparador (alta o reutiliza el vehículo); no se escribe a mano.';
comment on column public.envios.vehiculo_remolque_id is 'formato: uuid | → vehiculos.id | rango: no aplica | lista: no aplica | automático | Remolque de la flota (→ vehiculos.id) que corresponde a matricula_remolque. Lo pone un disparador; no se escribe a mano.';
comment on column public.envios.conductor_id is 'formato: uuid | → conductores.id | rango: no aplica | lista: no aplica | automático | Conductor de la flota (→ conductores.id) que corresponde a conductor_nombre/teléfono. Lo pone un disparador; no se escribe a mano.';
comment on column public.envios.matricula_camion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Matrícula del camión que carga: la cabeza tractora en un trailer, el rígido en un rígido. Copia congelada: el CMR antiguo sigue diciendo la que cargó. Ej. OK: 1234LBC';
comment on column public.envios.matricula_remolque is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Matrícula del remolque. Solo en trailer: un rígido no lleva remolque (lo impide tg_envios_vehiculos). Copia congelada. Ej. OK: R1234BCD';
comment on column public.envios.conductor_nombre is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Nombre del conductor (copia congelada). El cliente deja de verlo al entregar/cancelar o 12 h tras el día de entrega previsto. Ej. OK: Juan Pérez (inventado)';
comment on column public.envios.conductor_telefono is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Teléfono del conductor (copia congelada), con prefijo. Oculto al cliente al entregar/cancelar; se borra al anonimizar al conductor. Ej. OK: +34600000000 · Ej. mal: 600 00';
comment on column public.envios.transportista_nima is 'formato: texto | rango: no aplica | lista: no aplica | opcional | NIMA del transportista para residuos, copiado de su ficha al aceptar la carga si estaba vacío. Solo Dynamo y el transportista lo ven.';
comment on column public.envios.fecha_carga_desde is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Primer día de la ventana comercial de carga (día, hora de Madrid). Cliente: a partir de mañana y como mucho 120 días; fecha pasada solo el Admin Master. Ej. OK: 2026-11-20';
comment on column public.envios.fecha_carga_hasta is 'formato: fecha (AAAA-MM-DD) | rango: >= fecha_carga_desde | lista: no aplica | opcional | Último día de la ventana de carga (día). Igual o posterior a fecha_carga_desde; igual a ella si es fecha fija. Ej. OK: 2026-11-21 · Ej. mal: anterior a fecha_carga_desde';
comment on column public.envios.fecha_carga_real is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día en que se cargó de verdad. Se rellena solo al marcar en_ruta o entregado (marcar_mi_viaje, marcar_mi_envio_manual) si estaba vacío; Dynamo puede corregirlo.';
comment on column public.envios.fecha_entrega_estimada is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día previsto de entrega. Lo pone Dynamo; también decide cuándo se oculta al cliente el contacto del conductor.';
comment on column public.envios.descripcion_mercancia is 'formato: texto | longitud_max: 500 | rango: máx. 500 caracteres | lista: no aplica | opcional | Qué se transporta, en texto libre. Ej. OK: Palets de azulejo';
comment on column public.envios.toneladas is 'formato: número decimal (2 decimales) | rango: mayor que 0, 2 decimales | lista: no aplica | opcional | Peso de la carga en toneladas. Ej. OK: 24 · Ej. mal: 0';
comment on column public.envios.metros_lineales is 'formato: número decimal (2 decimales) | rango: mayor que 0, 2 decimales | lista: no aplica | opcional | Metros lineales de camión que ocupa la carga. Con 13,30 o más es carga completa. Ej. OK: 13.60 · Ej. mal: -2';
comment on column public.envios.tipo_carga is 'formato: lista cerrada (tipo_carga) | rango: no aplica | lista: completa, grupaje | automático | Completa o grupaje, calculado de metros_lineales (>= 13,30 m = completa). Columna generada: no se escribe.';
comment on column public.envios.paletizado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | La mercancía va en palets (casilla Paletizado de Wtransnet).';
comment on column public.envios.carga_lateral is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Se puede cargar por el lateral (Lateral en Wtransnet).';
comment on column public.envios.carga_superior is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Hay que cargar por arriba/techo (Arriba en Wtransnet). Implica suplemento de carga por techo.';
comment on column public.envios.carga_trasera is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Se puede cargar por detrás (Detrás en Wtransnet). Ojo: por defecto true en la tabla pero crear_envio() la pone false si no se indica.';
comment on column public.envios.carga_lateral_bajo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Sirve un lateral bajo (Sirve Lateral Bajo en Wtransnet). Ninguna función de alta lo rellena; solo a mano.';
comment on column public.envios.plataforma_elevadora is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Necesita camión rígido con plataforma elevadora (trampilla). En la bolsa sale como Rígido; sin ella, Trailer.';
comment on column public.envios.nima_requerido is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | La carga son residuos y el transporte exige NIMA del transportista.';
comment on column public.envios.adr is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Mercancía peligrosa (ADR).';
comment on column public.envios.importe_cliente is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Precio al cliente en euros, SIN IVA. Vacío en una solicitud hasta que Dynamo propone precio. Prohibido en envíos manuales. Ej. OK: 850.00 · Ej. mal: -10';
comment on column public.envios.importe_transportista is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Precio pagado al transportista en euros, SIN IVA. Lo fija la aceptación de la carga o Dynamo. Solo Dynamo lo ve. Prohibido en envíos manuales. Ej. OK: 720.00';
comment on column public.envios.moneda is 'formato: texto | longitud_fija: 3 | rango: no aplica | lista: no aplica | obligatorio | Moneda de los importes (código ISO de 3 letras). Hoy siempre EUR. Ej. OK: EUR · Ej. mal: €';
comment on column public.envios.margen_euros is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Margen de Dynamo en euros sin IVA = importe_cliente − importe_transportista. Columna generada. Solo Dynamo.';
comment on column public.envios.factor_tarifa_aplicado is 'formato: número decimal (2 decimales) | rango: numérico, 2 decimales (el factor del cliente va de −30 a +30) | lista: no aplica | opcional | Copia del factor de tarifa del cliente (%) aplicado a este envío. Hoy ninguna función lo rellena (llegará con el tarifador). Solo Dynamo. Ej. OK: -7.00';
comment on column public.envios.iva_aplicado is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | IVA (%) aplicado al cliente en este envío, congelado. crear_envio() pone 21 si no se indica; las solicitudes del cliente siempre 21. Ej. OK: 21 · Ej. mal: 0.21';
comment on column public.envios.retencion_aplicada is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | Retención (%) aplicada en este envío, congelada. Hoy ninguna función la rellena: la exportación a Holded usa la de la ficha del cliente si está vacía. Ej. OK: 0';
comment on column public.envios.plazo_pago_aplicado is 'formato: número entero | rango: no aplica | lista: no aplica | opcional | Plazo de pago (días) aplicado a este envío, congelado. Hoy ninguna función lo rellena: Holded usa el de la ficha del cliente si está vacío. Ej. OK: 60 · Ej. mal: -30';
comment on column public.envios.precio_fijado_a_mano is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | El precio al cliente lo puso una persona (no el tarifador). crear_envio() lo marca si llega importe_cliente; proponer_precio_solicitud() también.';
comment on column public.envios.codigo_postal_origen is 'formato: texto | rango: no aplica | lista: no aplica | automático | CP de la primera parada (origen). Copiado desde envio_paradas por el disparador tg_envios_ruta. NO se escribe a mano.';
comment on column public.envios.poblacion_origen is 'formato: texto | rango: no aplica | lista: no aplica | automático | Población de la primera parada (origen). La copia el disparador tg_envios_ruta desde envio_paradas.';
comment on column public.envios.codigo_postal_destino is 'formato: texto | rango: no aplica | lista: no aplica | automático | CP de la última parada (destino). Copiado por el disparador tg_envios_ruta. NO se escribe a mano.';
comment on column public.envios.poblacion_destino is 'formato: texto | rango: no aplica | lista: no aplica | automático | Población de la última parada (destino). La copia el disparador tg_envios_ruta.';
comment on column public.envios.num_paradas is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número de paradas de la ruta (cargas + descargas). Lo calcula el disparador tg_envios_ruta.';
comment on column public.envios.km_total is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Kilómetros totales: suma de km_hasta_siguiente de las paradas, por disparador. Hoy suele quedar vacío porque nadie rellena esos km.';
comment on column public.envios.pedido_venta_holded is 'formato: texto | rango: no aplica | lista: no aplica | automático | Nº de pedido de venta en Holded (hoy la propia referencia GX). Lo pone marcar_exportados(''venta''); vacío = aún no pasado a Holded.';
comment on column public.envios.pedido_compra_holded is 'formato: texto | rango: no aplica | lista: no aplica | automático | Nº de pedido de compra en Holded (la referencia GX). Lo pone marcar_exportados(''compra''); vacío = no pasado.';
comment on column public.envios.publicado_en_bolsa_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se publicó en la bolsa de cargas (instante, hora del servidor). Lo pone marcar_exportados(''bolsa'') y deja hito. Si se modifica después, se puede republicar.';
comment on column public.envios.discrecion_comercial is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | El cliente pide que no se revele su nombre: en el fichero de la bolsa la columna CLIENTE sale vacía (también si lo marca su ficha). Viaja en la orden de carga para que se respete.';
comment on column public.envios.anotaciones_cliente is 'formato: texto | longitud_max: 1000 | rango: máx. 1000 caracteres | lista: no aplica | opcional | Indicaciones del cliente sobre el envío, en texto libre. Nunca se publican en la bolsa (pueden llevar teléfonos o su cliente final).';
comment on column public.envios.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de creación de la fila (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envios.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos (auditoría); vacío si lo creó un proceso.';
comment on column public.envios.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos (auditoría).';
comment on column public.envios.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos (auditoría).';
comment on column public.envios.confirmado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo salió de borrador (instante). Lo pone un disparador; no se escribe a mano.';
comment on column public.envios.primera_oferta_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se ofertó por primera vez a un transportista (instante). Lo pone ofertar_envio(). Interno de Dynamo.';
comment on column public.envios.asignado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se asignó el transportista actual (instante). Lo pone un disparador al cambiar transportista_id.';
comment on column public.envios.cargado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo pasó a en_ruta, es decir, cargado (instante). Lo pone un disparador.';
comment on column public.envios.entregado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo pasó a entregado (instante). Lo pone un disparador.';
comment on column public.envios.cancelado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se canceló (instante). Lo pone un disparador; se vacía al deshacer la cancelación.';
comment on column public.envios.operador_id is 'formato: uuid | → operadores.id | rango: no aplica | lista: no aplica | opcional | Vacío = envío de DYNAMO. Con valor = envío MANUAL con ese operador del cliente (→ operadores.id, de su catálogo): Dynamo no interviene (sin ofertas, transportista ni precios de Dynamo).';
comment on column public.envios.precio_acordado_operador is 'formato: número decimal (2 decimales) | rango: >= 0; solo si operador_id tiene valor | lista: no aplica | opcional | Solo envíos manuales: lo que el cliente pactó con SU transportista, en euros sin IVA. Opcional. Sale en su orden de transporte. Ej. OK: 600.00';
comment on column public.envios.es_manual is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | true si es un envío manual (operador_id con valor). Columna generada.';
comment on column public.envios.facturado_venta is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Ya facturado al cliente (columna FACTURADO? de la venta de Holded). Se marca con marcar_facturados(''venta'').';
comment on column public.envios.facturado_compra is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | obligatorio | Ya recibida la factura del transportista (FACTURADO? de la compra). Se marca con marcar_facturados(''compra'').';
comment on column public.envios.valoracion_transportista is 'formato: número entero | rango: 1 a 5 | lista: no aplica | opcional | SOLO DYNAMO: nota de 1 a 5 al transportista en este envío; solo si está entregado y tiene transportista. Recalcula su media interna. Ej. OK: 4 · Ej. mal: 6';
comment on column public.envios.valoracion_comentario is 'formato: texto | rango: máx. 1000 caracteres | lista: no aplica | opcional | SOLO DYNAMO: comentario de la valoración interna del transportista.';
comment on column public.envios.solicitud_estado is 'formato: texto | rango: no aplica | lista: pendiente_precio (espera precio de Dynamo), precio_propuesto (espera respuesta del cliente), contraoferta (el cliente propuso otro precio), aceptada, rechazada | automático | Solo envíos pedidos por el CLIENTE desde el panel; null = creado por Dynamo. Lo mueven crear_solicitud_envio(), proponer_precio_solicitud(), responder_precio_solicitud() y la contraoferta.';
comment on column public.envios.precio_valido_hasta is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Hasta cuándo vale el precio propuesto a la solicitud (instante); por defecto 24 h (solicitud_validez_horas). Lo pone proponer_precio_solicitud().';
comment on column public.envios.condiciones_aceptadas_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Hora del SERVIDOR en que el cliente aceptó el precio y las condiciones generales (también al contraofertar). La ponen las funciones de respuesta.';
comment on column public.envios.numero_bultos is 'formato: número entero | rango: 1 a 99999 | lista: no aplica | opcional | Casilla 7 del CMR: número de bultos (palets, cajas…). Se pone con poner_datos_cmr() antes de cargar y sin firmas. Ej. OK: 26 · Ej. mal: 0';
comment on column public.envios.embalaje is 'formato: texto | rango: 1 a 60 caracteres | lista: no aplica | opcional | Casilla 8 del CMR: clase de embalaje. Se pone con poner_datos_cmr(). Ej. OK: Palet europeo';
comment on column public.envios.volumen_m3 is 'formato: número decimal (2 decimales) | rango: mayor que 0 y hasta 500 | lista: no aplica | opcional | Casilla 12 del CMR: volumen en m³. Se pone con poner_datos_cmr(). Ej. OK: 45.5 · Ej. mal: 0';
comment on column public.envios.negociacion_pct is 'formato: número entero | rango: no aplica | lista: 0 (precio fijo), 5, 10, 30 | opcional | Banda de negociación por defecto al ofertar (0 = precio fijo; 5/10 los decide el sistema; 30 lo revisa Dynamo). Vacío = la de siempre (10). Interno; el transportista nunca ve el %.';
comment on column public.envios.valoracion_cliente is 'formato: número entero | rango: 1 a 5 | lista: no aplica | opcional | Nota del CLIENTE (1-5) al transportista de su envío de Dynamo entregado. Solo con valorar_mi_envio(); la cambia 30 días. Nadie más la toca. Ej. OK: 5 · Ej. mal: 0';
comment on column public.envios.valoracion_cliente_comentario is 'formato: texto | rango: máx. 500 caracteres | lista: no aplica | opcional | Comentario del cliente en su valoración. Solo con valorar_mi_envio().';
comment on column public.envios.valoracion_cliente_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo valoró el cliente por primera vez (instante); desde ahí cuentan los 30 días para cambiarla. Lo pone valorar_mi_envio().';
comment on column public.envios.pago_previo is 'formato: texto | rango: no aplica | lista: no_requerido, pendiente (no se oferta ni se asigna), pagado (Stripe o transferencia), exento (Dynamo lo pasa a cobro a vencimiento) | automático | Pago por adelantado. Lo decide la base de datos al confirmar (sin crédito o primeros envíos) y lo cambian marcar_pago_envio() y pago_envio_stripe(). Pendiente: no se oferta ni asigna.';
comment on column public.envios.pago_motivo is 'formato: texto | rango: no aplica | lista: no aplica | automático | Por qué se pide pago previo (sin crédito, primer envío o pedido por Dynamo). Lo pone la base de datos o marcar_pago_envio(''requerir'').';
comment on column public.envios.pago_metodo is 'formato: texto | rango: no aplica | lista: stripe (tarjeta), transferencia | automático | Cómo se pagó. Lo ponen marcar_pago_envio(''transferencia'') o pago_envio_stripe().';
comment on column public.envios.pagado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se registró el pago (instante, hora del servidor). Lo ponen las funciones de pago.';
comment on column public.envios.pago_resuelto_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario de Dynamo que marcó la transferencia o el paso sin pago previo (→ auth.users.id). Lo pone marcar_pago_envio().';
comment on column public.envios.pago_exento_motivo is 'formato: texto | rango: 3 a 500 caracteres | lista: no aplica | opcional | Por qué Dynamo lo pasa sin pago previo (cobro a vencimiento). Obligatorio al marcar exento con marcar_pago_envio(). Ej. OK: Empresa conocida, CESCE positivo · Ej. mal: ok';
comment on column public.envios.stripe_pago is 'formato: texto | rango: no aplica | lista: no aplica | automático | Identificador del pago en Stripe (payment_intent). Lo pone solo el servidor con pago_envio_stripe(). Ej. OK: pi_000000000000';
comment on column public.envios.contraoferta_cliente is 'formato: número decimal (2 decimales) | rango: mayor que 0 y menor que importe_cliente | lista: no aplica | opcional | Precio en euros SIN IVA que propuso el cliente frente al nuestro (ver solicitud_estado). Solo con contraofertar_precio_solicitud(). Ej. OK: 800.00';
comment on column public.envios.contraoferta_cliente_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo propuso el cliente su contraoferta (instante). Lo pone contraofertar_precio_solicitud().';
comment on column public.envios.precio_inicial_cliente is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | El precio que dimos al cliente antes de que consiguiera otro con su contraoferta (euros sin IVA). Lo ponen las funciones de contraoferta.';
comment on column public.envios.precio_revisar is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | La ruta ha cambiado (hito ruta_cambiada) y el precio aún no se ha revisado. Se apaga solo al tocar importe_cliente o importe_transportista.';
comment on column public.envios.cambio_cliente is 'formato: JSON | rango: no aplica | lista: no aplica | automático | Último cambio pedido por el cliente (JSON: fecha_desde, fecha_hasta, detalle; o antes_desde/antes_hasta si se aplicó). Lo escribe pedir_cambio_envio().';
comment on column public.envios.cambio_cliente_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo pidió el cliente el cambio (instante). Lo pone pedir_cambio_envio().';
comment on column public.envios.cambio_cliente_estado is 'formato: texto | rango: no aplica | lista: pendiente (espera a Dynamo), aplicado (solo fechas, al momento), aceptado, rechazado | automático | Estado del cambio pedido por el cliente. Lo ponen pedir_cambio_envio() y resolver_cambio_envio().';
comment on column public.envios.cambio_cliente_nota is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Respuesta de Dynamo al cambio pedido. Se pone con resolver_cambio_envio().';
comment on column public.envios.cancelado_en_nombre_cliente is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | Dynamo lo canceló desde la vista del cliente (a petición suya): cuenta como cancelación del cliente. Lo pone cancelar_envio(); se limpia al deshacer.';
comment on column public.envios.pago_pendiente_desde is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Desde cuándo está pendiente de pago (instante), para el plazo previo_pago_horas; pasado, se anula solo. La pone la base de datos; ampliar_plazo_pago() la renueva.';
comment on column public.envios.precio_calculado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se puso el precio al cliente que tiene ahora (instante). Lo pone la base de datos al cambiar importe_cliente.';
comment on column public.envios.precio_revision is 'formato: texto | rango: no aplica | lista: pendiente (espera su fecha), revisar (toca hoy), esperando_cliente (sube: acepta o cancela), hecha (definitivo) | automático | Precio provisional (se programó con más de 7 días). Null = cerrado desde el principio. Mientras no esté hecha: no se oferta ni asigna. Lo llevan las funciones de revisión.';
comment on column public.envios.precio_revision_fecha is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | automático | Día en que toca revisar el precio provisional (3 días hábiles antes de la carga). Lo calcula la base de datos.';
comment on column public.envios.precio_revision_anterior is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Precio al cliente antes de la revisión (euros sin IVA). Lo pone revisar_precio_envio().';
comment on column public.envios.precio_revision_nuevo is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | automático | Precio resultante de la revisión (euros sin IVA); si sube, espera a que el cliente lo acepte. Lo pone revisar_precio_envio().';
comment on column public.envios.precio_revision_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se hizo la revisión o se cerró el precio (instante). Lo ponen las funciones de revisión.';
comment on column public.envios.precio_revision_recordado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | Ya se avisó a Dynamo de que el cliente no contesta a la subida (24 h). Lo pone revisar_precios_programados().';
comment on column public.envios.cancelacion_sin_coste is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | Cancelado sin coste para el cliente (no aceptó la subida de la revisión): no cuenta para su suspensión. Lo pone responder_subida_precio().';
comment on table public.festivos is 'Festivos nacionales (region vacía), autonómicos (region) y locales (region + poblacion), con regla de repetición. Los nacionales de España vienen sembrados como festivos que se repiten cada año. Los edita Dynamo. Se consultan con es_dia_habil() y festivos_entre(); los usa el corte de cancelación.';
comment on column public.festivos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del festivo.';
comment on column public.festivos.fecha is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | obligatorio | Si repetir = no, el día festivo. Si se repite, la primera vez que vale (desde ese día). Si es de Pascua, tiene que cuadrar con dias_desde_pascua. Ej. OK: 2026-12-08';
comment on column public.festivos.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | Código ISO de 2 letras del país del festivo. Ej. OK: ES · Ej. mal: es';
comment on column public.festivos.region is 'formato: texto | rango: patrón XX-YYY (país, guion, 1-3 letras/cifras) | lista: no aplica | opcional | Comunidad o región en código ISO 3166-2. Vacío = festivo de todo el país. Ej. OK: ES-AN · Ej. mal: Andalucía';
comment on column public.festivos.poblacion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Municipio de un festivo local; exige region. Vacío si no es local. Ojo: hoy es_dia_habil() y festivos_entre() no tienen en cuenta los locales. Ej. OK: Sevilla';
comment on column public.festivos.nombre is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre del festivo, tal como se enseña. Ej. OK: Inmaculada';
comment on column public.festivos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.festivos.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.festivos.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.festivos.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on column public.festivos.repetir is 'formato: texto | rango: no aplica | lista: no (solo esa fecha), cada_anio (mismo día y mes todos los años), pascua (a dias_desde_pascua del Domingo de Pascua de cada año) | obligatorio | Cómo se repite el festivo. Ej. OK: cada_anio · Ej. mal: anual';
comment on column public.festivos.dias_desde_pascua is 'formato: número entero | rango: no aplica | lista: no aplica | opcional | Días respecto al Domingo de Pascua (Jueves Santo = -3, Viernes Santo = -2, Lunes de Pascua = +1). Obligatorio si repetir = pascua y vacío en los demás. Ej. OK: -2 · Ej. mal: -2 con repetir = no';
comment on column public.festivos.vigente_hasta is 'formato: fecha (AAAA-MM-DD) | rango: >= fecha | lista: no aplica | opcional | Último día en que vale un festivo que se repite (date). Vacío = sin fin. No se usa con repetir = no. Ej. OK: 2030-12-31';
comment on table public.firmas_cmr is 'Append-only. Valor probatorio de cada firma del CMR digital: quién, con qué documento, cuándo (hora del servidor), desde dónde y la huella de lo firmado. Se escribe solo con firmar_cmr_publico() desde el enlace /cmr/<token>; no se edita ni se borra. La leen Dynamo y el cliente del envío.';
comment on column public.firmas_cmr.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la firma.';
comment on column public.firmas_cmr.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | automático | Envío cuyo CMR se firma (→ envios.id). Lo deduce firmar_cmr_publico() a partir del enlace de firma.';
comment on column public.firmas_cmr.parada_id is 'formato: uuid | rango: no aplica | lista: no aplica | opcional | Parada donde se firma (→ envio_paradas.id, sin clave ajena por ser append-only): una recogida para el remitente, una entrega para el destinatario; vacía para el transportista.';
comment on column public.firmas_cmr.rol is 'formato: texto | rango: no aplica | lista: remitente (casilla 22, el cargador, en una recogida), transportista (casilla 23, el porteador, sin parada), destinatario (casilla 24, en una entrega) | obligatorio | Casilla del CMR que se firma. Solo una firma por rol y parada en cada envío.';
comment on column public.firmas_cmr.nombre is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre de la persona que firma, tal como lo escribe. No puede quedar vacío. Ej. OK: Laura Gómez Ruiz';
comment on column public.firmas_cmr.documento is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Documento de identidad de quien firma (DNI, NIE, pasaporte…), en mayúsculas y sin espacios, puntos ni guiones. Dato personal: la página pública solo enseña los 4 últimos caracteres. Ej. OK: 12345678Z · Ej. mal: (vacío)';
comment on column public.firmas_cmr.documento_pais is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | País que emitió el documento, código ISO de 2 letras. La función pone «XX» si quien firma no lo indica. Ej. OK: ES · Ej. mal: esp';
comment on column public.firmas_cmr.documento_validado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | true si el documento pasó la comprobación de formato de su país (DNI, NIE…) en la página de firma.';
comment on column public.firmas_cmr.email is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Email de quien firma, si lo da (se guarda en minúsculas). Dato personal. Ej. OK: firmante@empresa-ejemplo.es · Ej. mal: firmante@';
comment on column public.firmas_cmr.firmado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se firmó (instante). La pone SIEMPRE el servidor con un disparador, aunque se mande otro valor.';
comment on column public.firmas_cmr.ip is 'formato: dirección IP | rango: no aplica | lista: no aplica | opcional | IP desde la que se firmó, la que pasa el servidor web a la función. Forma parte de la prueba de la firma. Ej. OK: 203.0.113.25 · Ej. mal: 203.0.113';
comment on column public.firmas_cmr.navegador is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Navegador de quien firma (user-agent), recortado a 400 caracteres.';
comment on column public.firmas_cmr.firma_storage_ruta is 'formato: texto | rango: cmr/<token del enlace>/<uuid>.png | lista: no aplica | obligatorio | Ruta de la imagen del trazo en el almacén privado «documentos». Tiene que estar ya subida en la carpeta del enlace usado. Ej. OK: cmr/3f6c2a9e-1b4d-4e8a-9c7f-2d5b8e1a6c40/9b1e7d34-5a2c-4f8e-8d61-0c3a7b2e9f15.png · Ej. mal: firmas/firma1.jpg';
comment on column public.firmas_cmr.sha256_documento is 'formato: texto | rango: 64 caracteres 0-9 y a-f, en minúscula | lista: no aplica | opcional | Huella SHA-256 de los datos del CMR que tenía delante quien firmó (reservas incluidas). Si llega mal formada, se guarda vacía. Ej. OK: e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855 · Ej. mal: E3B0C442';
comment on table public.incidencias is 'Incidencias (tickets) sobre un envío, un almacenamiento o sin ninguno (p. ej. una consulta de facturación). Las abren clientes, transportistas (de sus viajes; el cliente no las ve) o Dynamo; las reservas del CMR abren solas un siniestro (anotar_reservas_cmr()). Resolverlas es solo de Dynamo.';
comment on column public.incidencias.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la incidencia.';
comment on column public.incidencias.codigo is 'formato: texto | rango: patrón INC- + número (desde 10000) | lista: no aplica | automático | Código visible de la incidencia: «INC-» más un número de secuencia. Lo pone la base de datos. Ej. OK: INC-10023';
comment on column public.incidencias.tipo_id is 'formato: uuid | → tipos_incidencia.id | rango: no aplica | lista: no aplica | obligatorio | Tipo de incidencia (→ tipos_incidencia.id). Si es el tipo «siniestro», la prioridad pasa sola a crítica.';
comment on column public.incidencias.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | opcional | Cliente al que pertenece (→ clientes.id). Si no se indica, se toma del envío o del usuario que la abre. Vacío en las que abre un transportista (el cliente no las ve).';
comment on column public.incidencias.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | opcional | Envío afectado (→ envios.id). Opcional: se puede abrir en cualquier estado del envío o sin envío. Al crearla con envío se anota un hito en su historial.';
comment on column public.incidencias.almacenamiento_id is 'formato: uuid | → almacenamientos.id | rango: no aplica | lista: no aplica | opcional | Almacenamiento afectado (→ almacenamientos.id), si la incidencia es sobre un servicio de almacén.';
comment on column public.incidencias.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista implicado (→ transportistas.id). Si la abre un transportista, la base de datos pone el suyo.';
comment on column public.incidencias.titulo is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Resumen corto de la incidencia. No puede quedar vacío ni solo con espacios. Ej. OK: Palets dañados en la descarga';
comment on column public.incidencias.detalle is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Explicación libre de lo ocurrido. En las abiertas por una reserva del CMR, el texto de la reserva.';
comment on column public.incidencias.estado is 'formato: lista cerrada (estado_ticket) | rango: no aplica | lista: abierto, en_curso, resuelto, cancelado | opcional | Estado del ticket (abierto, en_curso, resuelto, cancelado). Quien la abrió solo puede retirarla (cancelado) mientras está abierta; resolverla es de Dynamo.';
comment on column public.incidencias.prioridad is 'formato: lista cerrada (prioridad_ticket) | rango: no aplica | lista: baja, media, alta, critica | opcional | Prioridad (baja, media por defecto, alta, crítica). Los siniestros entran siempre como crítica (disparador). Alta o crítica llegan a Dynamo como aviso urgente.';
comment on column public.incidencias.resuelto_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo pasó a resuelto (instante). La pone un disparador y la vacía si se reabre.';
comment on column public.incidencias.resolucion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Qué se hizo para cerrarla. Lo escribe Dynamo; su inicio sale en el aviso de «incidencia resuelta» a quien la abrió. Ej. OK: Se repuso la mercancía y se abonó el porte.';
comment on column public.incidencias.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.incidencias.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.incidencias.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.incidencias.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.intentos_carga_publica is 'Registro append-only de fallos y altas en la página pública «aceptar carga» (enlace de bolsa; el transportista se identifica con su CIF). Sirve para los topes: 5 fallos en una reserva la liberan y 20 en 24 h bloquean la carga (parámetros carga_publica_max_fallos_*). Lo escriben aceptar_oferta_publica() y alta_transportista_publica(). Solo Dynamo lo lee.';
comment on column public.intentos_carga_publica.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número correlativo del intento. Lo pone la base de datos.';
comment on column public.intentos_carga_publica.envio_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Carga (envío) del enlace (→ envios.id, sin clave ajena).';
comment on column public.intentos_carga_publica.reserva_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Reserva temporal de la carga en la que ocurrió (→ envio_reservas.id, sin clave ajena).';
comment on column public.intentos_carga_publica.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo ocurrió (instante, hora del servidor; un disparador la impone).';
comment on column public.intentos_carga_publica.motivo is 'formato: texto | rango: no aplica | lista: cif_no_encontrado (CIF que no está en Dynamo), alta_ya_existe (alta online con un CIF o código de bolsa ya registrado), alta_online (alta online hecha; cuenta para el tope diario) | automático | Qué pasó.';
comment on column public.intentos_carga_publica.ip is 'formato: dirección IP | rango: no aplica | lista: no aplica | automático | IP del visitante, la que pasa el servidor web.';
comment on table public.lugar_horarios is 'Horario de cada sitio: una fila por día de la semana y tramo (un día partido son dos filas). Día sin filas = cerrado. Temporada general o de verano. Sirve para horas de llegada y avisos de sitio cerrado. Se guarda con guardar_horario() / guardar_horario_verano(), no fila a fila.';
comment on column public.lugar_horarios.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del tramo.';
comment on column public.lugar_horarios.lugar_id is 'formato: uuid | → lugares.id | rango: no aplica | lista: no aplica | obligatorio | Sitio al que pertenece el horario (→ lugares.id).';
comment on column public.lugar_horarios.dia_semana is 'formato: número entero | rango: 1 a 7 | lista: no aplica | obligatorio | Día de la semana del tramo, 1 = lunes … 7 = domingo. Ej. OK: 1 (lunes) · Ej. mal: 0';
comment on column public.lugar_horarios.abre is 'formato: hora (HH:MM) | rango: no aplica | lista: no aplica | obligatorio | Hora de apertura del tramo (hora local del sitio, sin zona). Los tramos de un mismo día y temporada no pueden pisarse. Ej. OK: 08:00 · Ej. mal: 8h';
comment on column public.lugar_horarios.cierra is 'formato: hora (HH:MM) | rango: mayor que abre | lista: no aplica | obligatorio | Hora de cierre del tramo; tiene que ser posterior a abre (no hay tramos que pasen de medianoche: se parten en dos días). Ej. OK: 14:00 · Ej. mal: 02:00 con abre 22:00';
comment on column public.lugar_horarios.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.lugar_horarios.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.lugar_horarios.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.lugar_horarios.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on column public.lugar_horarios.temporada is 'formato: texto | rango: no aplica | lista: general (todo el año), verano (solo en las fechas de verano del sitio) | obligatorio | A qué horario pertenece el tramo. El de verano solo se usa si el sitio tiene verano_activo y la fecha cae entre verano_desde y verano_hasta. Ej. OK: general · Ej. mal: invierno';
comment on table public.lugares is 'Agenda de sitios de carga y descarga (almacenes, naves, obras, fincas…). Cada ficha es de un cliente, salvo los almacenes de Dynamo (de nadie, los ven todos). Se escribe directamente; el horario con guardar_horario() / guardar_horario_verano() y la estrella de sitio principal con marcar_sitio_principal().';
comment on column public.lugares.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del sitio.';
comment on column public.lugares.codigo is 'formato: texto | rango: L- + número (desde L-10000) | lista: no aplica | automático | Código legible del sitio, L- más un número correlativo. Lo pone la base de datos. Ej. OK: L-10234';
comment on column public.lugares.nombre_empresa is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre de la empresa o del sitio tal como se muestra en la agenda (una obra puede llevar el nombre de la obra). No puede ir vacío. Ej. OK: Logística Ejemplo S.L. · Ej. mal: (texto vacío)';
comment on column public.lugares.cif is 'formato: texto | rango: no aplica | lista: no aplica | opcional | CIF/NIF de la empresa del sitio. Opcional: una obra o una finca no siempre lo tienen. Ej. OK: B12345678';
comment on column public.lugares.tipo is 'formato: lista cerrada (tipo_lugar) | rango: no aplica | lista: almacen_nave, obra_zona_amplia, obra_zona_urbana, finca | obligatorio | Tipo de sitio. De él depende el recargo del tarifador (ver recargos_tipo_lugar). Por defecto almacén/nave.';
comment on column public.lugares.direccion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Calle y número, SOLO eso (el CP, la población y la provincia van en sus columnas). Ej. OK: Calle Ejemplo 12, nave 3 · Ej. mal: Calle Ejemplo 12, 41001 Sevilla';
comment on column public.lugares.codigo_postal is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Código postal, SIEMPRE como texto: hay CP no españoles (2400-016 PT, 85-453 PL, N41 RW27 IE) y 08185 como número perdería el cero. Ej. OK: 08185 · Ej. mal: 8185';
comment on column public.lugares.poblacion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Población o municipio del sitio. Ej. OK: Sevilla';
comment on column public.lugares.provincia is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Provincia (o región equivalente fuera de España) del sitio. Ej. OK: Sevilla';
comment on column public.lugares.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | Código ISO de 2 letras del país, en mayúsculas. El nombre del país se saca de aquí al enseñarlo. Ej. OK: ES · Ej. mal: España';
comment on column public.lugares.lat is 'formato: número decimal (6 decimales) | rango: -90 a 90 | lista: no aplica | opcional | Latitud de la dirección (grados decimales), de la geocodificación. Si cambia, sube version_geo y se recalculan los km. Ej. OK: 37.389100 · Ej. mal: 95';
comment on column public.lugares.lon is 'formato: número decimal (6 decimales) | rango: -180 a 180 | lista: no aplica | opcional | Longitud de la dirección (grados decimales), de la geocodificación. Si cambia, sube version_geo y se recalculan los km. Ej. OK: -5.984500 · Ej. mal: 200';
comment on column public.lugares.horarios is 'formato: texto | rango: no aplica | lista: no aplica | automático | Resumen legible del horario general, sacado de lugar_horarios. Lo escribe la base de datos: lo que se escriba a mano se sustituye. Ej. OK: L-J 8:00-14:00 y 15:00-17:30 · V 8:00-14:00';
comment on column public.lugares.url_google_maps is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Enlace de Google Maps al sitio, para el conductor (sale en Mis viajes y en la página pública de la carga). Ej. OK: https://maps.google.com/?q=37.3891,-5.9845';
comment on column public.lugares.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas del cliente sobre su sitio ("preguntar por el encargado", "entrar por la puerta de atrás"). Solo las ven ese cliente y Dynamo.';
comment on column public.lugares.es_almacen_dynamo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Verdadero si es un almacén de Dynamo (sin cliente_id, lo ven todos los clientes). Solo lo cambia Dynamo.';
comment on column public.lugares.disponible is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Interruptor "Almacén disponible/Completo". Completo bloquea crear ALMACENAMIENTOS, pero el sitio sigue sirviendo como recogida o entrega. Solo lo cambia Dynamo.';
comment on column public.lugares.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | obligatorio | Cliente dueño de la ficha (→ clientes.id). Cada cliente tiene las suyas aunque dos carguen en la misma nave. Vacío solo en almacenes Dynamo. Si lo crea un cliente, lo pone la base de datos.';
comment on column public.lugares.borrado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Borrado SUAVE: el sitio desaparece de la agenda y del buscador, pero no se borra (los envíos ya creados conservan su dirección).';
comment on column public.lugares.borrado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo se marcó como borrado (instante, timestamptz). La pone la base de datos al poner borrado = true y la vacía al recuperarlo.';
comment on column public.lugares.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.lugares.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.lugares.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.lugares.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on column public.lugares.version_geo is 'formato: número entero | rango: entero desde 1 | lista: no aplica | automático | Versión de las coordenadas: sube sola cuando cambian lat/lon (la empresa se muda). Forma parte de la clave de distancias_lugares, así los km viejos dejan de valer. No tocar a mano.';
comment on column public.lugares.exige_pin is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | El conductor tiene que validar un PIN al cargar/descargar aquí. Previsto para una fase posterior: hoy no se genera ningún PIN.';
comment on column public.lugares.requiere_cita is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Solo carga/descarga con cita previa (por defecto no). Sirve para avisar al transportista antes de que el camión llegue y no le carguen.';
comment on column public.lugares.tiene_medios_carga is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Hay medios de carga/descarga (muelle, carretilla…). Por defecto sí. Si es no, hace falta camión con trampilla elevadora.';
comment on column public.lugares.emails_avisos is 'formato: lista de text | rango: máx. 10 emails válidos | lista: no aplica | opcional | Emails que reciben avisos de las recogidas y entregas en este sitio, con total discreción (sin precios ni otros clientes). No son personas: las personas van en contactos. Ej. OK: {muelle@ejemplo.com} · Ej. mal: {muelle-ejemplo.com}';
comment on column public.lugares.precio_almacenamiento_semana is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Solo almacenes Dynamo: precio propio en euros sin IVA de un tráiler completo 7 días. Vacío = el de parametros (almacen_precio_semana). Un sitio de cliente no puede tenerlo. Ej. OK: 240.00 · Ej. mal: -5';
comment on column public.lugares.precio_reparto is 'formato: número decimal (2 decimales) | rango: >= 0 | lista: no aplica | opcional | Solo almacenes Dynamo: precio propio en euros sin IVA por reparto urbano con camión de 4 m. Vacío = el de parametros (almacen_precio_reparto). Ej. OK: 220.00 · Ej. mal: -1';
comment on column public.lugares.verano_activo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | El sitio usa horario de verano (lugar_horarios temporada verano) entre verano_desde y verano_hasta, cada año. Se cambia con guardar_horario_verano().';
comment on column public.lugares.verano_desde is 'formato: texto | rango: formato MM-DD | lista: no aplica | opcional | Primer día del horario de verano, mes-día (se repite cada año). Obligatorio si verano_activo. Se rellena con guardar_horario_verano(). Ej. OK: 06-15 · Ej. mal: 15/06';
comment on column public.lugares.verano_hasta is 'formato: texto | rango: formato MM-DD | lista: no aplica | opcional | Último día del horario de verano, mes-día (se repite cada año; puede cruzar el año). Obligatorio si verano_activo. Se rellena con guardar_horario_verano(). Ej. OK: 09-15 · Ej. mal: 9-15';
comment on column public.lugares.horarios_verano is 'formato: texto | rango: no aplica | lista: no aplica | automático | Resumen legible del horario de verano, sacado de lugar_horarios. Lo escribe la base de datos. Ej. OK: L-V 7:30-15:00';
comment on table public.notas_internas is 'Notas del equipo de Dynamo sobre una ficha (usuario, cliente, transportista, camión, conductor o almacenamiento). SOLO DYNAMO las lee y escribe. Una por ficha y campo. Se escriben con guardar_nota_interna() o guardando la columna anotaciones (o incidencias_notas) de la ficha: un disparador mueve el texto aquí y deja la columna vacía.';
comment on column public.notas_internas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la nota.';
comment on column public.notas_internas.tabla is 'formato: texto | rango: no aplica | lista: usuarios, clientes, transportistas, vehiculos, conductores, almacenamientos | obligatorio | Tabla de la ficha a la que pertenece la nota.';
comment on column public.notas_internas.campo is 'formato: texto | rango: no aplica | lista: anotaciones (notas generales, por defecto), incidencias_notas (notas sobre incidencias; solo en transportistas) | opcional | Qué nota de la ficha es.';
comment on column public.notas_internas.registro_id is 'formato: uuid | rango: no aplica | lista: no aplica | obligatorio | id de la ficha dentro de la tabla indicada en «tabla» (p. ej. clientes.id). Sin clave ajena porque puede apuntar a varias tablas. Ej. OK: 3f6c2a9e-1b4d-4e8a-9c7f-2d5b8e1a6c40';
comment on column public.notas_internas.texto is 'formato: texto | rango: hasta 5000 caracteres | lista: no aplica | obligatorio | Texto de la nota. Si se guarda vacía con guardar_nota_interna(), la nota se borra. Ej. OK: Prefiere que le llamen por la mañana. · Ej. mal: (texto de más de 5000 caracteres)';
comment on column public.notas_internas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.notas_internas.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.notas_internas.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.notas_internas.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.operadores is 'Catálogo PRIVADO de transportistas de cada cliente, para sus envíos manuales (envios.operador_id). No es la red de Dynamo (transportistas): Dynamo no los usa ni los mezcla. Se escribe directamente: cada cliente solo los suyos; borrar es suave (borrado) y el borrado real solo Dynamo.';
comment on column public.operadores.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del operador.';
comment on column public.operadores.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | obligatorio | Cliente dueño de este catálogo → clientes.id. Si lo crea el propio cliente se rellena solo con el suyo; Dynamo tiene que indicarlo.';
comment on column public.operadores.razon_social is 'formato: texto | rango: no puede estar vacío | lista: no aplica | obligatorio | Nombre fiscal o comercial del transportista del cliente. Sale en su orden de transporte y en el CMR del envío manual. Ej. OK: Transportes Ejemplo e Hijos S.L. · Ej. mal: (vacío)';
comment on column public.operadores.cif is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | CIF/NIF del operador. No puede repetirse dentro del catálogo de un mismo cliente (sin contar los borrados; se compara sin guiones ni espacios). Ej. OK: B11223344 · Ej. mal: B-11223344 si ya está en su catálogo';
comment on column public.operadores.telefono is 'formato: texto | rango: + opcional y de 6 a 15 cifras, sin espacios ni guiones | lista: no aplica | opcional | Teléfono del operador en formato internacional sin espacios. Ej. OK: +34600111222 · Ej. mal: 600 11 12 22';
comment on column public.operadores.email is 'formato: texto | rango: formato nombre@dominio.ext | lista: no aplica | opcional | Email del operador. Ej. OK: trafico@ejemplo.es · Ej. mal: trafico@ejemplo';
comment on column public.operadores.persona_contacto is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Nombre de la persona de contacto en el operador (texto libre). Ej. OK: Luis Martín';
comment on column public.operadores.web is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Página web del operador. Ej. OK: https://www.ejemplo.es';
comment on column public.operadores.logo_url is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Sin uso: el logo para la orden de transporte se sube como documento (tabla documentos, tipo logo, con operador_id).';
comment on column public.operadores.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas libres del cliente sobre este operador.';
comment on column public.operadores.borrado is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Borrado suave: true = quitado del catálogo y de Nuevo envío, pero los envíos ya hechos con él lo conservan. Va junto con borrado_en.';
comment on column public.operadores.borrado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Instante (timestamptz) en que se quitó del catálogo. Obligatorio si borrado es true y vacío si es false; lo pone la aplicación al borrar.';
comment on column public.operadores.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.operadores.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.operadores.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.operadores.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on table public.parametros is 'Ajustes del negocio que se cambian sin tocar código (plazos, topes, precios por defecto, datos fijos de Dynamo…): una fila por clave. Lee Dynamo; solo el administrador escribe. IBAN, banco, BIC, razón social y CIF de Dynamo solo se cambian desde Supabase. Se lee con parametro(clave).';
comment on column public.parametros.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la fila (lo usa la auditoría).';
comment on column public.parametros.clave is 'formato: texto | rango: patrón ^[a-z][a-z0-9_]*$ | lista: no aplica | obligatorio | Nombre del parámetro, único, en minúsculas con guiones bajos. Si falta una clave que pide el sistema, parametro() da error. Ej. OK: almacen_precio_semana · Ej. mal: Almacen-Precio';
comment on column public.parametros.valor is 'formato: JSON | rango: no aplica | lista: no aplica | obligatorio | Valor en JSON (jsonb): números tal cual, textos como cadena JSON entre comillas, listas como array. Importes en euros sin IVA salvo que la descripción diga otra cosa. Ej. OK: 240 · "05-25" · ["ES","PT"] · Ej. mal: 05-25 (texto sin comillas)';
comment on column public.parametros.descripcion is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Explicación en lenguaje claro de qué controla el parámetro y en qué unidad va. Ej. OK: Precio por defecto (EUR sin IVA) de almacenar un tráiler 7 días.';
comment on column public.parametros.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.parametros.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.parametros.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.parametros.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on table public.penalizaciones is 'Penalizaciones y cargos extra de un envío (cancelación tardía, paralización, parada adicional…): lo que se cobra al cliente y lo que se paga al transportista. Solo Dynamo escribe; la de cancelar tarde con camión la crea sola un disparador. Cliente y transportista las ven con mis_penalizaciones() y mis_penalizaciones_transportista().';
comment on column public.penalizaciones.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la penalización.';
comment on column public.penalizaciones.codigo is 'formato: texto | rango: patrón PEN- + número (desde 10000) | lista: no aplica | automático | Código visible: «PEN-» más un número de secuencia. Lo pone la base de datos. Ej. OK: PEN-10007';
comment on column public.penalizaciones.envio_id is 'formato: uuid | → envios.id | rango: no aplica | lista: no aplica | obligatorio | Envío al que se aplica (→ envios.id).';
comment on column public.penalizaciones.tipo_id is 'formato: uuid | → tipos_penalizacion.id | rango: no aplica | lista: no aplica | obligatorio | Tipo de penalización (→ tipos_penalizacion.id). La de clave «paralizacion» va a Holded como concepto de paralización; el resto, como penalización.';
comment on column public.penalizaciones.descripcion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Explicación libre. Sale en la línea del pedido de Holded y la ven el cliente y el transportista. Ej. OK: Espera de 4 h en el muelle de descarga';
comment on column public.penalizaciones.importe_cliente is 'formato: número decimal (2 decimales) | rango: 0 o más | lista: no aplica | opcional | Lo que se cobra al cliente, en euros SIN IVA. Vacío si no se le cobra. Tiene que haber al menos uno de los dos importes. Ej. OK: 150.00 · Ej. mal: -20';
comment on column public.penalizaciones.importe_transportista is 'formato: número decimal (2 decimales) | rango: 0 o más | lista: no aplica | opcional | Lo que se paga al transportista, en euros SIN IVA. Vacío si no le corresponde. El cliente nunca lo ve. Ej. OK: 120.00 · Ej. mal: -5';
comment on column public.penalizaciones.estado is 'formato: lista cerrada (estado_penalizacion) | rango: no aplica | lista: pendiente_confirmar, confirmada, cancelada | opcional | pendiente_confirmar (por defecto), confirmada (se factura en Holded y avisa al cliente y al transportista) o cancelada (retirada; nunca se borra).';
comment on column public.penalizaciones.generada_auto is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | true si la creó sola la base de datos al cancelar con camión asignado después del corte (9:00 de Madrid del día hábil anterior a la carga).';
comment on column public.penalizaciones.editada_a_mano is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | true si Dynamo ha tocado los importes de una penalización automática (lo marca un disparador). Si se deshace la cancelación, una automática sin tocar se retira sola; una editada, no.';
comment on column public.penalizaciones.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.penalizaciones.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.penalizaciones.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.penalizaciones.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.pin_intentos is 'Registro append-only de cada intento de validar el PIN de una parada (aciertos, fallos y rechazos), contra la fuerza bruta y para detectar fraude. Lo escribe solo validar_pin_parada(); no se edita ni se borra (salvo la limpieza RGPD a 90 días, hoy apagada). Solo Dynamo lo lee.';
comment on column public.pin_intentos.id is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número correlativo del intento. Lo pone la base de datos.';
comment on column public.pin_intentos.parada_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Parada cuyo PIN se intentó (→ envio_paradas.id, sin clave ajena por ser append-only).';
comment on column public.pin_intentos.envio_id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Envío de la parada (→ envios.id, sin clave ajena).';
comment on column public.pin_intentos.cuando is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Cuándo fue el intento (instante, hora del servidor; un disparador la impone).';
comment on column public.pin_intentos.acierto is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | automático | true si el PIN era correcto y el punto quedó validado.';
comment on column public.pin_intentos.motivo is 'formato: texto | rango: no aplica | lista: ok (acierto), pin_incorrecto, bloqueado (el PIN ya estaba bloqueado), envio_no_activo (sin transportista o envío no en curso), demasiado_pronto / demasiado_tarde (fuera de la ventana horaria), faltan_puntos_anteriores | automático | Resultado del intento.';
comment on column public.pin_intentos.ip is 'formato: dirección IP | rango: no aplica | lista: no aplica | automático | IP del conductor, la que pasa el servidor web.';
comment on column public.pin_intentos.navegador is 'formato: texto | rango: no aplica | lista: no aplica | automático | Navegador del conductor (user-agent), recortado a 400 caracteres.';
comment on table public.recargos_tipo_lugar is 'Catálogo con vigencia del recargo del tarifador según el tipo de sitio (almacén, obra, finca…). Una fila por tipo y fecha de inicio; un cambio de porcentaje es una fila nueva para que lo antiguo se recalcule con el de entonces. Solo Dynamo. Porcentajes provisionales: aún no lo usa ninguna función.';
comment on column public.recargos_tipo_lugar.tipo is 'formato: lista cerrada (tipo_lugar) | rango: no aplica | lista: almacen_nave, obra_zona_amplia, obra_zona_urbana, finca | obligatorio | Tipo de sitio al que se aplica el recargo (el mismo que lugares.tipo). Junto con vigente_desde es la clave.';
comment on column public.recargos_tipo_lugar.porcentaje is 'formato: número decimal (2 decimales) | rango: 0 a 100 | lista: no aplica | obligatorio | Recargo en % sobre el precio del porte (5 = 5 %). Ej. OK: 20.00 · Ej. mal: 120';
comment on column public.recargos_tipo_lugar.vigente_desde is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | obligatorio | Primer día en que vale este porcentaje (date). Por defecto, hoy. Ej. OK: 2026-01-01';
comment on column public.recargos_tipo_lugar.vigente_hasta is 'formato: fecha (AAAA-MM-DD) | rango: >= vigente_desde | lista: no aplica | opcional | Último día en que vale (date). Vacío = sigue vigente. Ej. OK: 2026-12-31 · Ej. mal: anterior a vigente_desde';
comment on table public.restricciones_servicio is 'Excepciones de servicio: dónde no se carga o descarga, o solo en camión completo. Una fila por regla, con interruptor y vigencia; solo afecta a los envíos que se generan desde ese momento. Los países atendidos están en parametros (cobertura_paises). Editable solo por Dynamo; se consulta con fn_restriccion_punto() y comprobar_cobertura().';
comment on column public.restricciones_servicio.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único de la regla.';
comment on column public.restricciones_servicio.nombre is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre de la regla para la tabla del panel. No puede ir vacío. Ej. OK: Baleares solo completo · Ej. mal: (texto vacío)';
comment on column public.restricciones_servicio.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas | lista: no aplica | obligatorio | Código ISO de 2 letras del país al que se aplica. Ej. OK: ES · Ej. mal: Suiza';
comment on column public.restricciones_servicio.prefijos_cp is 'formato: lista de text | rango: al menos un prefijo, ninguno vacío | lista: no aplica | opcional | Vacío (NULL) = el país entero. Si no, prefijos de CP del territorio: Canarias {35,38}, Baleares {07}, Ceuta/Melilla {51,52}. Ej. OK: {35,38} · Ej. mal: {}';
comment on column public.restricciones_servicio.aplica_a is 'formato: texto | rango: no aplica | lista: carga (no recogemos ahí), descarga (no entregamos ahí, sí recogemos), cualquier_punto (no se pasa por ahí) | obligatorio | A qué paradas afecta. Se habla de cargas y descargas, no de origen/destino, para coger también las paradas intermedias. Ej. OK: descarga · Ej. mal: destino';
comment on column public.restricciones_servicio.tipo_carga is 'formato: lista cerrada (tipo_carga) | rango: no aplica | lista: completa, grupaje | opcional | Vacío = cualquier tipo de carga. ''grupaje'' prohíbe solo el grupaje (caso de Baleares: se va en completo porque viaja el tráiler entero en el barco).';
comment on column public.restricciones_servicio.efecto is 'formato: texto | rango: no aplica | lista: bloquea (no se puede, ni Dynamo), solo_admin (el cliente no puede pedirlo; Dynamo sí lo registra), avisa (se deja pasar con aviso) | obligatorio | Qué pasa si una parada cae en la regla. Ej. OK: bloquea · Ej. mal: prohibe';
comment on column public.restricciones_servicio.mensaje is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Texto que ve el cliente cuando choca con la regla. Que no destape nada interno. Ej. OK: De momento no entregamos en Canarias. · Ej. mal: (texto vacío)';
comment on column public.restricciones_servicio.activa is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Interruptor de ahora mismo: apagarla abre ese destino al instante, sin desplegar nada, y la fila conserva su historia. Las fechas de vigencia son para cambios planificados.';
comment on column public.restricciones_servicio.vigente_desde is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Primer día en que se aplica la regla (date). Por defecto, hoy. Ej. OK: 2027-01-01';
comment on column public.restricciones_servicio.vigente_hasta is 'formato: fecha (AAAA-MM-DD) | rango: >= vigente_desde | lista: no aplica | opcional | Último día en que se aplica (date). Vacío = sin fin. Ej. OK: 2027-06-30 · Ej. mal: anterior a vigente_desde';
comment on column public.restricciones_servicio.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos con la hora del servidor.';
comment on column public.restricciones_servicio.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que dio de alta la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno.';
comment on column public.restricciones_servicio.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.restricciones_servicio.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). La pone la base de datos.';
comment on table public.tipos_incidencia is 'Catálogo de tipos de incidencia (incidencia en el transporte, cancelación, cambio de fecha, facturación, pago, albarán, siniestro, transportista/conductor, otros). Solo Dynamo lo edita; para jubilar un tipo se desactiva en vez de borrarlo. Lo leen todos los usuarios con sesión.';
comment on column public.tipos_incidencia.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del tipo.';
comment on column public.tipos_incidencia.clave is 'formato: texto | rango: minúscula inicial y luego minúsculas, cifras o _ | lista: no aplica | obligatorio | Identificador fijo del tipo, en minúsculas. El código usa «siniestro» (prioridad crítica, reservas del CMR, aviso urgente): no cambiarla. Ej. OK: cambio_fecha_hora_carga · Ej. mal: Parada-Adicional';
comment on column public.tipos_incidencia.nombre is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre que se enseña en el panel. Ej. OK: Consulta de facturación';
comment on column public.tipos_incidencia.activo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es false, el tipo deja de ofrecerse para nuevas altas, pero los registros antiguos lo conservan. Es la forma de jubilarlo (no borrar).';
comment on column public.tipos_incidencia.orden is 'formato: número entero | rango: no aplica | lista: no aplica | opcional | Posición en el desplegable (menor = más arriba). Ej. OK: 4';
comment on column public.tipos_incidencia.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.tipos_incidencia.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.tipos_incidencia.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.tipos_incidencia.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.tipos_penalizacion is 'Catálogo de tipos de penalización (cancelación, paralización, compensación, parada adicional, otro). Solo Dynamo lo edita; para jubilar un tipo se desactiva en vez de borrarlo, así no se rompe el histórico. Lo leen todos los usuarios con sesión.';
comment on column public.tipos_penalizacion.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del tipo.';
comment on column public.tipos_penalizacion.clave is 'formato: texto | rango: minúscula inicial y luego minúsculas, cifras o _ | lista: no aplica | obligatorio | Identificador fijo del tipo, en minúsculas. El código usa algunas («cancelacion» para la automática, «paralizacion» para Holded): no cambiarlas. Ej. OK: parada_adicional · Ej. mal: Parada-Adicional';
comment on column public.tipos_penalizacion.nombre is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | Nombre que se enseña en el panel y en Holded. Ej. OK: Parada adicional';
comment on column public.tipos_penalizacion.activo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es false, el tipo deja de ofrecerse para nuevas altas, pero los registros antiguos lo conservan. Es la forma de jubilarlo (no borrar).';
comment on column public.tipos_penalizacion.orden is 'formato: número entero | rango: no aplica | lista: no aplica | opcional | Posición en el desplegable (menor = más arriba). Ej. OK: 4';
comment on column public.tipos_penalizacion.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, en UTC). La pone la base de datos y no se puede cambiar.';
comment on column public.tipos_penalizacion.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). La pone la base de datos; vacío si la creó un proceso interno o una migración.';
comment on column public.tipos_penalizacion.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de la última modificación (instante, en UTC). La pone la base de datos; vacío si nunca se ha modificado.';
comment on column public.tipos_penalizacion.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo la última modificación (→ auth.users.id). La pone la base de datos.';
comment on table public.transportistas is 'Red de transportistas de Dynamo (proveedores): datos fiscales (Holded), bolsa de carga, seguro y datos internos (estado, valoraciones). Escribe Dynamo; el transportista lee con mi_empresa_transportista() y cambia NIMA y seguro con mi_transporte_guardar(). Alta online: alta_transportista_publica().';
comment on column public.transportistas.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del transportista. Es el que usan las relaciones (transportista_id).';
comment on column public.transportistas.codigo is 'formato: texto | rango: T- + número, desde 10000 | lista: no aplica | automático | Código legible para hablar por teléfono (T-10042). Lo pone la base de datos con una secuencia. Ej. OK: T-10042';
comment on column public.transportistas.razon_social is 'formato: texto | rango: no puede estar vacío | lista: no aplica | obligatorio | Nombre fiscal completo. Es el «Nombre» que se exporta a Holded. Ej. OK: Autotransportes Ejemplo S.L. · Ej. mal: (vacío o solo espacios)';
comment on column public.transportistas.cif is 'formato: texto | rango: no aplica | lista: no aplica | obligatorio | CIF/NIF fiscal. Único entre transportistas (se compara sin guiones, puntos ni espacios y en mayúsculas); el mismo CIF puede ser además cliente. Ej. OK: B87654321 · Ej. mal: b-87654321 si ya existe B87654321';
comment on column public.transportistas.direccion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Calle y número del domicilio fiscal. Ej. OK: Polígono Sur, nave 4';
comment on column public.transportistas.poblacion is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Población del domicilio fiscal. Ej. OK: Zaragoza';
comment on column public.transportistas.codigo_postal is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Código postal del domicilio fiscal. Texto, para no perder el cero inicial. Ej. OK: 08040 · Ej. mal: 8040';
comment on column public.transportistas.provincia is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Provincia del domicilio fiscal. Ej. OK: Zaragoza';
comment on column public.transportistas.pais_codigo_iso is 'formato: texto | longitud_fija: 2 | rango: 2 letras mayúsculas (ISO 3166-1) | lista: no aplica | opcional | País del domicilio fiscal en código ISO de 2 letras; el nombre se saca de aquí al enseñarlo. Por defecto ES. Ej. OK: PT · Ej. mal: es';
comment on column public.transportistas.iva_porcentaje is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | IVA (%) de sus facturas a Dynamo. Por defecto 21. Ojo: aquí la base de datos no limita el valor. Ej. OK: 21';
comment on column public.transportistas.retencion_porcentaje is 'formato: número decimal (2 decimales) | rango: no aplica | lista: no aplica | opcional | Retención (%) en sus facturas (normalmente 0). Aquí la base de datos no limita el valor. Ej. OK: 1';
comment on column public.transportistas.forma_pago_holded_id is 'formato: texto | rango: no aplica | lista: no aplica | opcional | ID de la forma de pago en Holded. Se exporta tal cual en el pedido de compra. Ej. OK: 5f2a0c1e9b3d4a0012ab34cd';
comment on column public.transportistas.cuenta_contable is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Cuenta contable del transportista (contabilidad / Holded). Hoy no la usa ninguna exportación. Ej. OK: 40000123';
comment on column public.transportistas.moneda is 'formato: texto | longitud_fija: 3 | rango: 3 letras | lista: no aplica | opcional | Moneda en código ISO de 3 letras. Por defecto EUR. Hoy no la usa ninguna pantalla ni exportación. Ej. OK: EUR · Ej. mal: €';
comment on column public.transportistas.tags is 'formato: lista de text | rango: no aplica | lista: no aplica | opcional | Etiquetas; se exportan a Holded unidas con «-». alta_online = se dio de alta él solo desde el enlace de una carga (pendiente de verificar). Ej. OK: {alta_online}';
comment on column public.transportistas.plazo_pago_dias is 'formato: número entero | rango: no aplica | lista: 0 (contado), 30, 60 (por defecto), 90 | opcional | Días en que Dynamo le paga sus portes. Por defecto 60. El pronto pago lo adelanta. Ej. OK: 60 · Ej. mal: 120';
comment on column public.transportistas.nima is 'formato: texto | rango: máx. 40 caracteres desde su panel | lista: no aplica | opcional | NIMA (número de gestor de residuos) del TRANSPORTISTA, no del cliente ni del envío: lo aporta al aceptar una carga de residuos. Lo cambian Dynamo o él (mi_transporte_guardar). Ej. OK: 4100012345';
comment on column public.transportistas.codigo_bolsa is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Su código de socio en la bolsa de carga indicada en bolsa. Si hay código tiene que haber bolsa. Ej. OK: 482113';
comment on column public.transportistas.almacen_logistico is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si el transportista tiene almacén logístico propio. Informativo, lo marca Dynamo.';
comment on column public.transportistas.tipo_camion_defecto is 'formato: lista cerrada (tipo_camion) | rango: no aplica | lista: trailer_tauliner, rigido_plataforma | opcional | Camión habitual del transportista (vacío = sin preferencia). Informativo, lo pone Dynamo.';
comment on column public.transportistas.seguro_cmr_compania is 'formato: texto | rango: máx. 120 caracteres desde su panel | lista: no aplica | opcional | Compañía de su seguro de mercancías (CMR). Lo cambian Dynamo o él desde su panel. Ej. OK: Aseguradora Ejemplo';
comment on column public.transportistas.seguro_cmr_poliza is 'formato: texto | rango: máx. 60 caracteres desde su panel | lista: no aplica | opcional | Número de póliza del seguro CMR. Lo cambian Dynamo o él desde su panel. Ej. OK: POL-2026-0001';
comment on column public.transportistas.seguro_cmr_vence is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día (date) en que vence el seguro CMR, para avisar antes de darle una carga. Lo cambian Dynamo o él. Ej. OK: 2027-03-31 · Ej. mal: 31/03/2027';
comment on column public.transportistas.estado_operativo is 'formato: lista cerrada (estado_operativo_transportista) | rango: no aplica | lista: activo, no_ofertar, suspendido | opcional | SOLO DYNAMO, él nunca lo ve. activo = se le ofertan cargas y carga; no_ofertar = no recibe ofertas pero puede cargar (así nacen las altas online); suspendido = ni ofertar ni cargar.';
comment on column public.transportistas.valoracion_dynamo is 'formato: número decimal (1 decimales) | rango: 0 a 5, un decimal | lista: no aplica | automático | SOLO DYNAMO: media de las notas internas (1-5) que Dynamo pone en sus envíos entregados. La recalcula la base de datos; él no la ve.';
comment on column public.transportistas.valoracion_dynamo_votos is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número de envíos con nota interna de Dynamo que forman la media. Lo recalcula la base de datos.';
comment on column public.transportistas.incidencias_notas is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Historial de incidencias en texto libre (retrasos, daños, no presentados…). Solo Dynamo.';
comment on column public.transportistas.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas internas de Dynamo; él no las ve. En las altas online se rellena sola con desde qué carga, cuándo y desde qué IP se dio de alta.';
comment on column public.transportistas.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.transportistas.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.transportistas.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.transportistas.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on column public.transportistas.nombre_comercial is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Opcional: cómo se le conoce. Si está vacío se usa la razón social. Ej. OK: Autotrans';
comment on column public.transportistas.nombre_visible is 'formato: texto | rango: no aplica | lista: no aplica | automático | Calculada por la base de datos: el nombre comercial si lo hay, si no la razón social. Es la de listados.';
comment on column public.transportistas.bolsa is 'formato: texto | rango: no aplica | lista: wtransnet, teleroute, bursa_transport, 123cargo | opcional | Bolsa de carga (grupo Alpega) en la que está dado de alta. Vacío = no tiene, y su alta queda pendiente de revisión. Ej. OK: wtransnet · Ej. mal: timocom';
comment on column public.transportistas.pronto_pago is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | SOLO DYNAMO. Si es false, sus ofertas salen siempre sin pronto pago aunque la línea general esté encendida. Por defecto true.';
comment on column public.transportistas.valoracion_clientes is 'formato: número decimal (1 decimales) | rango: 0 a 5, un decimal | lista: no aplica | automático | INTERNO: media de las notas (1-5) que los clientes ponen a sus envíos entregados. La recalcula la base de datos; él no la ve.';
comment on column public.transportistas.valoracion_clientes_votos is 'formato: número entero | rango: no aplica | lista: no aplica | automático | Número de notas de clientes que forman esa media. Lo recalcula la base de datos.';
comment on table public.usuarios is 'Perfil de cada cuenta con login (su id es el de auth.users). Se crea solo al registrarse, como cliente pendiente de verificación. Sin contraseñas (Supabase Auth). Rol, estado, empresa, límites, copias y suspensión solo los cambia Dynamo; el Admin Master solo se nombra desde Supabase.';
comment on column public.usuarios.id is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Identificador de la cuenta, el mismo que auth.users.id. El perfil se crea solo al registrarse en Supabase Auth.';
comment on column public.usuarios.email is 'formato: texto | rango: no aplica | lista: no aplica | automático | Email de la cuenta: copia del de auth.users, sincronizada por la base de datos. Único (sin mayúsculas). Solo lo cambian Dynamo o el sistema. Ej. OK: ana@ejemplo.es';
comment on column public.usuarios.nombre is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Nombre de la persona. Se toma del formulario de registro y se puede corregir. Ej. OK: Ana Pérez';
comment on column public.usuarios.documento is 'formato: texto | rango: no aplica | lista: no aplica | opcional | DATO PERSONAL (RGPD): DNI/NIE, solo donde hace falta (firma del CMR). Solo se anonimiza a mano si la persona lo pide. Ej. OK: 12345678Z';
comment on column public.usuarios.telefono is 'formato: texto | rango: + opcional y de 6 a 15 cifras, sin espacios ni guiones | lista: no aplica | opcional | Teléfono de la persona en formato internacional sin espacios. Ej. OK: +34600111222 · Ej. mal: 600 11 12 22';
comment on column public.usuarios.rol is 'formato: lista cerrada (rol_usuario) | rango: no aplica | lista: admin, empleado, cliente, transportista, admin_lectura, empleado_lectura | opcional | Tipo de cuenta. admin = Admin Master (solo desde Supabase), empleado = gestor de Dynamo, *_lectura = solo lectura, cliente, transportista. Nace cliente; solo Dynamo lo cambia.';
comment on column public.usuarios.estado is 'formato: lista cerrada (estado_cuenta) | rango: no aplica | lista: activa, suspendida, pendiente_verificacion | opcional | Estado de la cuenta. Nace pendiente_verificacion; solo Dynamo la activa o suspende (nunca la propia) y no vuelve a pendiente. Solo con activa se entra al panel.';
comment on column public.usuarios.cliente_id is 'formato: uuid | → clientes.id | rango: no aplica | lista: no aplica | opcional | Empresa cliente a la que pertenece → clientes.id. Obligatorio si es cliente y la cuenta está activa; nunca a la vez que transportista_id. Solo Dynamo.';
comment on column public.usuarios.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Transportista al que pertenece → transportistas.id. Obligatorio si es transportista y la cuenta está activa; nunca a la vez que cliente_id. Solo Dynamo.';
comment on column public.usuarios.limite_consultas_precio_diario is 'formato: número entero | rango: mayor que 0 | lista: no aplica | opcional | Tope de consultas de precio al día para este usuario; si lo supera, se suspende solo. Vacío = el general (parámetro autosusp_consultas_dia). Solo Dynamo. Ej. OK: 20 · Ej. mal: 0';
comment on column public.usuarios.limite_cargas_diario is 'formato: número entero | rango: mayor que 0 | lista: no aplica | opcional | Tope de envíos al día para este usuario. Solo Dynamo. Ojo: hoy la base de datos no lo aplica. Ej. OK: 10 · Ej. mal: 0';
comment on column public.usuarios.ultima_conexion is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | opcional | Sin uso: la última conexión se lee de auth.users (conexiones_usuarios()) y de los latidos del panel, no de esta columna.';
comment on column public.usuarios.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas internas de Dynamo sobre la cuenta. Solo las cambian Dynamo o el sistema.';
comment on column public.usuarios.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.usuarios.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.usuarios.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.usuarios.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';
comment on column public.usuarios.idioma is 'formato: texto | rango: 2 letras minúsculas y, si hace falta, región: es, pl, zh-CN | lista: no aplica | opcional | Idioma del portal y de los emails a este usuario. Por defecto es. Ej. OK: pl · Ej. mal: ES';
comment on column public.usuarios.cargo is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Puesto de la persona, texto libre. Ej. OK: Administración';
comment on column public.usuarios.sin_autosuspension is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si es true, a este usuario no se le suspende nunca automáticamente (clientes especiales). Solo Dynamo.';
comment on column public.usuarios.autosusp_desde is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Desde cuándo cuentan las reglas de suspensión automática (si está vacío, desde el alta). La pone la base de datos al reactivar la cuenta.';
comment on column public.usuarios.suspendida_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Instante (timestamptz) en que se suspendió la cuenta. Lo pone la base de datos al suspenderla y lo vacía al reactivarla.';
comment on column public.usuarios.suspension_motivo is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Por qué se suspendió (regla automática o a mano). Si Dynamo no pone motivo, la base de datos escribe «Suspendida a mano por Dynamo.». Se borra al reactivar. Ej. OK: Más de 15 consultas de precio en un día';
comment on column public.usuarios.copias_avisos is 'formato: lista de text | rango: máx. 10 emails válidos | lista: no aplica | opcional | Emails que reciben copia de los avisos de este usuario (para cuando salgan por email). Solo Dynamo. Ej. OK: {admin@ejemplo.es} · Ej. mal: {admin@ejemplo}';
comment on table public.vehiculos is 'Flota: camiones, tractoras y remolques, una fila por matrícula (vengan con quien vengan). Se dan de alta solos al poner matrículas en un envío de Dynamo (disparador), los gestiona el transportista con mi_vehiculo_guardar() / mi_flota_baja(), y Dynamo los escribe directamente.';
comment on column public.vehiculos.id is 'formato: uuid | rango: no aplica | lista: no aplica | automático | Identificador único del vehículo.';
comment on column public.vehiculos.codigo is 'formato: texto | rango: V- + número, desde 10000 | lista: no aplica | automático | Código legible (V-10042). Lo pone la base de datos con una secuencia. Ej. OK: V-10042';
comment on column public.vehiculos.transportista_id is 'formato: uuid | → transportistas.id | rango: no aplica | lista: no aplica | opcional | Con quién suele venir → transportistas.id (opcional). No lo ata: el mismo camión puede venir subcontratado por otro transportista.';
comment on column public.vehiculos.matricula is 'formato: texto | rango: 4 a 15 letras o cifras sin contar espacios ni guiones | lista: no aplica | obligatorio | Matrícula. Se compara sin espacios ni guiones y en mayúsculas, y es única entre los vehículos activos. No se cambia: otra matrícula es otro vehículo. Ej. OK: 1234 LBC · Ej. mal: 12-A';
comment on column public.vehiculos.tipo is 'formato: lista cerrada (tipo_vehiculo) | rango: no aplica | lista: tractora, remolque, rigido | obligatorio | Qué es: tractora, remolque o rígido. La pareja tractora+remolque de cada envío no se guarda aquí, sale del histórico de envíos. Un rígido no lleva remolque.';
comment on column public.vehiculos.itv_vence is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día (date) en que vence la ITV. Lo cambian Dynamo o el transportista. Ej. OK: 2027-05-15 · Ej. mal: 15/05/2027';
comment on column public.vehiculos.seguro_vence is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día (date) en que vence el seguro del vehículo. Ej. OK: 2027-01-31 · Ej. mal: 31-01-27';
comment on column public.vehiculos.tarjeta_transporte_vence is 'formato: fecha (AAAA-MM-DD) | rango: no aplica | lista: no aplica | opcional | Día (date) en que vence la tarjeta de transporte. Ej. OK: 2028-06-30 · Ej. mal: junio 2028';
comment on column public.vehiculos.adr is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si el vehículo está autorizado para mercancías peligrosas (ADR).';
comment on column public.vehiculos.trampilla is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | Si el vehículo lleva plataforma elevadora (trampilla).';
comment on column public.vehiculos.activo is 'formato: sí/no (true/false) | rango: no aplica | lista: no aplica | opcional | false = dado de baja (mi_flota_baja). No se borra; su matrícula puede volver a darse de alta.';
comment on column public.vehiculos.anotaciones is 'formato: texto | rango: no aplica | lista: no aplica | opcional | Notas libres sobre el vehículo.';
comment on column public.vehiculos.creado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora de alta de la fila (instante, timestamptz). La pone la base de datos y no se puede cambiar.';
comment on column public.vehiculos.creado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que creó la fila (→ auth.users.id). Lo pone la base de datos; vacío si la creó el sistema.';
comment on column public.vehiculos.modificado_en is 'formato: fecha y hora con zona (ISO 8601) | rango: no aplica | lista: no aplica | automático | Fecha y hora del último cambio (instante, timestamptz). La pone la base de datos; vacío si nunca se modificó.';
comment on column public.vehiculos.modificado_por is 'formato: uuid | → users.id | rango: no aplica | lista: no aplica | automático | Usuario que hizo el último cambio (→ auth.users.id). Lo pone la base de datos.';

comment on function public.aceptar_oferta_publica(p_reserva uuid, p_cif text, p_precio numeric, p_pronto_pago boolean, p_camion text, p_remolque text, p_conductor text, p_telefono text, p_ip inet) is '[Ofertas y transportistas] Enlace público de una carga: el transportista acepta la carga que tiene reservada. Si la oferta no es personal, se identifica con su CIF (ya dado de alta); cada CIF no encontrado cuenta como fallo y al llegar al tope pierde la reserva. Si queda aceptada guarda matrículas y conductor. Devuelve jsonb {resultado, transportista}. Quién: público con reserva (anon o con sesión). Argumentos: p_reserva: envio_reservas.id · p_cif: CIF del transportista (si la oferta no es personal) · p_precio: precio propuesto dentro de la banda (null = el ofertado) · p_pronto_pago: pide pronto pago · p_camion/p_remolque: matrículas · p_conductor, p_telefono: datos del conductor · p_ip: IP de quien llama.';
comment on function public.almacenes_dynamo_tarifa() is '[Sitios y horarios] Lista los almacenes de Dynamo (no borrados) con su dirección, si están disponibles y su tarifa (precio por semana y por reparto, sin IVA). Ordenados por provincia y población. Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.alta_transportista_publica(p_reserva uuid, p_bolsa text, p_codigo_bolsa text, p_pais character, p_cif text, p_telefono text, p_precio numeric, p_pronto_pago boolean, p_ip inet) is '[Ofertas y transportistas] Enlace público de una carga (oferta no personal): un transportista que aún no está en Dynamo se da de alta con bolsa, código, país, CIF y teléfono. Crea la ficha en estado no_ofertar con etiqueta alta_online y deja la reserva pendiente de revisión por Dynamo. Con topes de intentos y altas al día. Devuelve jsonb {resultado}. Quién: público con reserva (anon o con sesión). Argumentos: p_reserva: envio_reservas.id · p_bolsa: wtransnet, teleroute, bursa_transport o 123cargo · p_codigo_bolsa: su código en esa bolsa (máx. 30) · p_pais: ISO de 2 letras · p_cif · p_telefono (6-15 cifras) · p_precio: dentro de la banda (null = el ofertado) · p_pronto_pago · p_ip.';
comment on function public.altas_pendientes() is '[Clientes y cuentas] Usuarios que se han registrado y aún no están ligados a ningún cliente ni transportista (estado pendiente_verificacion), con si han confirmado el email y los datos que dejaron al registrarse. Los más recientes primero. Quién: Dynamo (también solo lectura). Argumentos: sin argumentos.';
comment on function public.ampliar_plazo_pago(p_envio uuid) is '[Precio y pago] Reinicia el plazo para pagar un envío con pago previo pendiente (vuelve a contar desde ahora), para que no se anule por impago. Solo si está programado y con el pago pendiente. Devuelve {resultado: ok | no_pendiente}. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id.';
comment on function public.anonimizar_conductor(p_conductor uuid) is '[Protección de datos] RGPD: borra los datos personales de un conductor (nombre genérico, sin documento ni teléfono) y sus notas internas. En los envíos se borra su teléfono pero se mantiene el nombre (forma parte del CMR). Devuelve {resultado: ok | no_existe}. Quién: solo el Admin Master. Argumentos: p_conductor: conductores.id.';
comment on function public.anonimizar_contacto(p_contacto uuid) is '[Protección de datos] RGPD: vacía los datos personales de una persona de contacto y borra la ficha. Devuelve {resultado: ok | no_existe}. Quién: solo el Admin Master. Argumentos: p_contacto: contactos.id.';
comment on function public.anonimizar_usuario(p_usuario uuid) is '[Protección de datos] RGPD: borra los datos personales de un usuario cliente o transportista (nombre genérico, email anónimo, sin documento ni teléfono), lo deja suspendido, borra sus notas internas y las fichas de contacto con su email. No sirve para usuarios de Dynamo. Devuelve {resultado, email_anonimo}. Quién: solo el Admin Master. Argumentos: p_usuario: usuarios.id.';
comment on function public.anotar_reservas_cmr(p_token uuid, p_parada uuid, p_rol text, p_texto text) is '[CMR y PIN] Enlace público del CMR: anota reservas u observaciones (p. ej. daños) en la casilla de quien firma, antes de firmar. Crea también una incidencia de siniestro en el envío. No se puede en casillas ya firmadas ni en envíos cancelados; máx. 3 por casilla y 10 por envío. Devuelve {resultado}. Quién: público con token del CMR. Argumentos: p_token: token del enlace del CMR · p_parada: envio_paradas.id (carga para remitente, descarga para destinatario, null para transportista) · p_rol: remitente, transportista o destinatario · p_texto: 3 a 1000 caracteres.';
comment on function public.autores_mis_envios() is '[Envíos] Para cada envío del cliente que llama: quién lo creó (nombre y email) y quién lo modificó por última vez (si fue alguien de Dynamo sale solo «Dynamo», si fue el transportista «Transportista») y cuándo. Quién: cliente (usuario de un cliente). Argumentos: sin argumentos.';
comment on function public.autosuspender_cuentas() is '[Sistema y tareas automáticas] Suspende las cuentas activas que cumplen los motivos de suspensión automática (los de autosuspension_candidatos). No hace nada si el parámetro autosusp_activa está apagado. Devuelve cuántas suspendió. Quién: Admin Master o servidor (tarea diaria). Argumentos: sin argumentos.';
comment on function public.autosuspension_candidatos() is '[Clientes y cuentas] Lista los usuarios que se suspenderían automáticamente ahora y el motivo. Solo consulta, no cambia nada. A quien no es de Dynamo ni servidor le devuelve vacío. Quién: Dynamo (también solo lectura) y servidor. Argumentos: sin argumentos.';
comment on function public.buscar_envios(p_q text, p_limite integer) is '[Envíos] Buscador de envíos: devuelve los ids de los envíos que contienen TODAS las palabras buscadas (sin distinguir mayúsculas ni acentos) en referencias, cliente, transportista, CIF, mercancía, matrículas, poblaciones, CP o paradas. Más recientes primero. Solo los envíos que quien llama puede ver. Quién: cualquier usuario con sesión (cada uno ve lo suyo por RLS). Argumentos: p_q: texto a buscar (palabras separadas por espacios) · p_limite: máximo de resultados (por defecto 500, tope 2000).';
comment on function public.buscar_persona(p_texto text) is '[Protección de datos] RGPD: busca a una persona en usuarios, contactos y conductores por email, nombre, teléfono o documento (mín. 3 caracteres; teléfono y documento sin espacios ni guiones). Devuelve tipo, id, datos, empresa y estado (máx. 100). Para atender peticiones de acceso o borrado. Quién: solo el Admin Master. Argumentos: p_texto: lo que se busca (mín. 3 caracteres).';
comment on function public.caducar_pagos_pendientes() is '[Sistema y tareas automáticas] Anula (pasa a cancelado) los envíos programados con pago previo pendiente, sin transportista, cuyo plazo de pago venció hace más de 45 minutos. Deja un hito con el motivo. Devuelve cuántos anuló. Quién: servidor (tarea automática), consola o Dynamo. Argumentos: sin argumentos.';
comment on function public.cambiar_ruta_envio(p_envio uuid, p_paradas jsonb) is '[Envíos] Reescribe las paradas de un envío antes de cargar: mantiene las que llegan con id, borra las que faltan y crea las nuevas (de un sitio guardado o a mano; opcionalmente las guarda en la agenda del cliente). De 2 a 4 puntos. No si ya cargó o el CMR tiene firmas. Valida la ruta y deja un hito con el antes y el después. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id · p_paradas: array jsonb en orden; cada parada {id (si se mantiene), tipo carga|descarga, lugar_id, o nombre_empresa, direccion, codigo_postal, poblacion, provincia, pais_codigo_iso, guardar_en_agenda, tipo_lugar; referencia, anotaciones}.';
comment on function public.cancelar_envio(p_envio uuid, p_motivo text, p_en_nombre_cliente boolean) is '[Envíos] Cancela un envío desde la ficha (en cualquier estado salvo ya cancelado). Guarda el motivo en un hito. Si se marca en nombre del cliente (p. ej. lo pidió por teléfono) cuenta como cancelación suya a efectos de suspensión automática. Devuelve {penalizacion, importe} si se generó penalización automática. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id · p_motivo: texto libre (máx. 500) · p_en_nombre_cliente: true si la cancela Dynamo a petición del cliente.';
comment on function public.cancelar_mi_envio(p_envio uuid, p_motivo text) is '[Envíos] El cliente cancela uno de sus envíos. Solo en borrador o programado (si el camión ya va hacia la carga, hay que llamar a Dynamo). Una solicitud de precio abierta queda rechazada. Devuelve {resultado, penalizacion, importe} por si la cancelación tarde genera penalización. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id · p_motivo: texto libre (máx. 500).';
comment on function public.carga_aceptada_publica(p_reserva uuid) is '[Ofertas y transportistas] Enlace público de una carga: estado de la reserva (viva, caducada, pendiente_revision, reasignada…) y, si está aceptada, todos los datos para hacer el viaje (fechas, mercancía, paradas con horarios y contacto, matrículas, conductor, precio y condiciones de pronto pago). Solo consulta. Quién: público con reserva (anon o con sesión). Argumentos: p_reserva: envio_reservas.id.';
comment on function public.cliente_del_usuario() is '[Ayudantes internos] Ayudante de reglas por fila: id del cliente del usuario que llama si es un usuario de cliente con cuenta activa; si no, null. Quién: cualquiera (devuelve null si no es cliente). Argumentos: sin argumentos.';
comment on function public.cmr_publico(p_token uuid) is '[CMR y PIN] Enlace público del CMR: datos para ver y firmar la carta de porte (referencia, remitente, porteador, transportista, matrículas, conductor, fecha de carga, mercancía, paradas y firmas ya hechas con el documento enmascarado). Solo consulta. Quién: público con token del CMR. Argumentos: p_token: token del enlace del CMR.';
comment on function public.cmr_ruta_permitida(p_name text) is '[CMR y PIN] Ayudante del almacenamiento de ficheros: dice si una ruta de imagen de firma (cmr/<token>/<uuid>.png) corresponde a un enlace de CMR válido. Lo usa la regla del bucket para dejar subir firmas sin sesión. Quién: público (lo usa la regla del bucket). Argumentos: p_name: ruta del fichero en el bucket.';
comment on function public.completar_carga_publica(p_reserva uuid, p_camion text, p_remolque text, p_conductor text, p_telefono text) is '[Ofertas y transportistas] Enlace público de una carga ya aceptada: el transportista completa o corrige matrícula del camión y del remolque, nombre y teléfono del conductor. Solo mientras el envío siga suyo y esté programado o hacia la carga. Ojo: los campos vacíos se borran. Devuelve {resultado}. Quién: público con reserva aceptada. Argumentos: p_reserva: envio_reservas.id (aceptada) · p_camion, p_remolque: matrículas (se quitan espacios y guiones) · p_conductor: nombre · p_telefono: mín. 6 cifras.';
comment on function public.comprobar_cobertura(p_paradas jsonb, p_tipo_carga tipo_carga) is '[Distancias y cobertura] Antes de crear un envío: comprueba cada parada contra las restricciones y la cobertura por país y CP. Devuelve solo las paradas que bloquean o que solo Dynamo puede aceptar, con su mensaje. Vacío = todo bien. Quién: cualquier usuario con sesión. Argumentos: p_paradas: array jsonb [{orden, tipo carga|descarga, pais, codigo_postal, nombre}] · p_tipo_carga: tipo de carga del envío (opcional).';
comment on function public.conexiones_usuarios() is '[Clientes y cuentas] Última conexión y si tiene el email confirmado de cada usuario (datos que viven en el sistema de autenticación). A quien no es de Dynamo le devuelve vacío. Quién: Dynamo (también solo lectura). Argumentos: sin argumentos.';
comment on function public.contadores_panel() is '[Avisos y panel] Números del menú lateral y de la campana según quien llama: Dynamo (sin asignar, sin pagar, incidencias, penalizaciones, almacenamientos, altas), cliente (lo suyo) o transportista (incidencias y penalizaciones). jsonb con un contador por clave. Quién: cualquier usuario con sesión (RLS de quien llama). Argumentos: sin argumentos.';
comment on function public.contraofertar_precio_solicitud(p_envio uuid, p_importe numeric) is '[Precio y pago] El cliente propone un precio más bajo al que le ha dado Dynamo en su solicitud. Si la rebaja no pasa del % automático se acepta y el envío queda programado; si pasa del máximo se rechaza; en medio queda pendiente de Dynamo. Necesita que el cliente lo tenga permitido; con tope de intentos al día. Devuelve {resultado}. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id (solicitud con precio propuesto) · p_importe: precio que propone, en euros sin IVA.';
comment on function public.corte_cancelacion(p_fecha_carga date, p_pais character, p_region text) is '[Calendario y festivos] Hora límite para cancelar gratis un envío con camión asignado: las 9:00 (hora de Madrid) del día hábil anterior a la carga, saltando fines de semana y festivos del país/región. Devuelve el instante (timestamptz). Quién: cualquier usuario con sesión. Argumentos: p_fecha_carga: día de carga · p_pais: ISO 2 letras (por defecto ES) · p_region: código de región para festivos regionales (opcional).';
comment on function public.crear_envio(p_envio jsonb, p_paradas jsonb) is '[Envíos] Dynamo crea un envío completo para un cliente con sus paradas en una sola operación y lo deja programado (al confirmar se comprueban ruta y zonas y se sellan los hitos). Puede fijar precio de cliente y de transportista. Devuelve id y referencia GX. Quién: Dynamo (admin o empleado). Argumentos: p_envio: jsonb {cliente_id (obligatorio), referencia_cliente, fecha_carga_desde, fecha_carga_hasta, descripcion_mercancia, toneladas, metros_lineales, paletizado, carga_lateral/trasera/superior, plataforma_elevadora, nima_requerido, adr, importe_cliente, importe_transportista (sin IVA), iva_aplicado, discrecion_comercial, anotaciones_cliente} · p_paradas: array de 2 a 4 paradas {tipo carga|descarga, lugar_id o datos de dirección, guardar_en_agenda, referencia, anotaciones}.';
comment on function public.crear_envio_manual(p_envio jsonb, p_paradas jsonb) is '[Envíos] El cliente crea un envío «manual»: lo mueve con su propio operador de transporte (no lo gestiona Dynamo), para tener sus papeles y seguimiento en la plataforma. Fecha de recogida de hoy en adelante. Queda programado. Devuelve id y referencia GX. Quién: cliente (usuario activo de un cliente). Argumentos: p_envio: jsonb {operador_id (uno de sus operadores, obligatorio), fecha_carga_desde, fecha_carga_hasta, referencia_cliente, mercancía, toneladas, metros_lineales, opciones de carga, precio_acordado_operador, discrecion_comercial, anotaciones_cliente (máx. 1000)} · p_paradas: array de 2 a 4 {tipo, lugar_id o dirección, guardar_en_agenda, contacto_nombre, contacto_telefono, referencia}.';
comment on function public.crear_solicitud_envio(p_envio jsonb, p_paradas jsonb) is '[Envíos] El cliente pide un envío a Dynamo: queda en borrador con la solicitud pendiente de precio, hasta que Dynamo proponga uno (proponer_precio_solicitud). Fecha de recogida a partir de mañana; 2 a 4 paradas; valida la ruta. Devuelve id y referencia GX. Quién: cliente (usuario activo de un cliente). Argumentos: p_envio: jsonb {fecha_carga_desde, fecha_carga_hasta, referencia_cliente, descripcion_mercancia, toneladas, metros_lineales, paletizado, carga_*, plataforma_elevadora, nima_requerido, adr, discrecion_comercial, anotaciones_cliente} · p_paradas: array de 2 a 4 {tipo, lugar_id o dirección, guardar_en_agenda, contacto_nombre, contacto_telefono, referencia, anotaciones}.';
comment on function public.datos_cmr_envio(p_envio uuid) is '[CMR y PIN] Datos extra del CMR de un envío: número de bultos, embalaje, volumen en m³ y si ya tiene alguna firma. Quién: Dynamo, cliente o transportista del envío. Argumentos: p_envio: envios.id.';
comment on function public.datos_dynamo() is '[Clientes y cuentas] Datos de empresa de Dynamo (razón social, CIF, dirección, teléfonos…) para pintarlos en documentos. Salen de los parámetros que empiezan por dynamo_ (sin el prefijo). Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.datos_orden_manual(p_envio uuid) is '[Envíos] Datos para la orden de carga de un envío manual del cliente (el que mueve con su propio operador): envío, cliente con su contacto de tráfico, porteador (el operador) y paradas. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id (envío manual).';
comment on function public.datos_orden_publica(p_reserva uuid) is '[Ofertas y transportistas] Enlace público de una carga aceptada: datos completos de la orden de carga para el transportista. Solo si la reserva está aceptada y el envío sigue asignado a ese transportista. Quién: público con reserva aceptada. Argumentos: p_reserva: envio_reservas.id.';
comment on function public.datos_orden_transportista(p_envio uuid) is '[Ofertas y transportistas] Datos completos de la orden de carga de un viaje, para el transportista asignado (desde su panel). Quién: transportista del envío. Argumentos: p_envio: envios.id.';
comment on function public.deshacer_cancelacion(p_envio uuid) is '[Envíos] Ficha del envío: devuelve un envío cancelado al estado que tenía antes de cancelarse (o a programado si no se sabe o era borrador). Devuelve el estado al que vuelve. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id (cancelado).';
comment on function public.dias_habiles_antes(p_fecha date, p_n integer) is '[Calendario y festivos] Fecha que queda N días hábiles (España, sin fines de semana ni festivos) antes de una fecha dada. Quién: cualquier usuario con sesión. Argumentos: p_fecha: fecha de partida · p_n: número de días hábiles hacia atrás.';
comment on function public.domingo_de_pascua(p_anio integer) is '[Calendario y festivos] Fecha del Domingo de Pascua de un año (cálculo de Gauss). Base de los festivos móviles (Semana Santa…). Quién: cualquiera. Argumentos: p_anio: año (p. ej. 2027).';
comment on function public.emails_validos(p text[]) is '[Ayudantes internos] Comprueba que una lista de emails tiene como mucho 10 y todos con formato válido. Se usa en restricciones de tablas (p. ej. copias de avisos). Quién: cualquiera. Argumentos: p: array de emails.';
comment on function public.en_temporada(p_fecha date, p_desde text, p_hasta text) is '[Ayudantes internos] Dice si un día cae dentro de una temporada anual dada como MM-DD (admite temporadas que cruzan el año, p. ej. 12-15 a 01-10). Falso si falta algún extremo. Quién: cualquiera. Argumentos: p_fecha: día · p_desde, p_hasta: inicio y fin en formato MM-DD.';
comment on function public.enlace_cmr_publico(p_reserva uuid) is '[CMR y PIN] Enlace público de una carga aceptada: devuelve el token del enlace para firmar el CMR del envío; si no hay uno vigente, revoca los viejos y crea otro. No para envíos en borrador o cancelados. Quién: público con reserva aceptada. Argumentos: p_reserva: envio_reservas.id (aceptada, envío aún asignado a ese transportista).';
comment on function public.envio_del_cliente(p_envio uuid) is '[Ayudantes internos] Ayudante de permisos: true si el envío es del cliente del usuario que llama. Quién: cualquier usuario con sesión. Argumentos: p_envio: envios.id.';
comment on function public.envio_del_transportista(p_envio uuid) is '[Ayudantes internos] Ayudante de permisos: true si el envío está asignado al transportista del usuario que llama. Quién: cualquier usuario con sesión. Argumentos: p_envio: envios.id.';
comment on function public.envios_que_cuentan(p_cliente uuid) is '[Ayudantes internos] Número de envíos de un cliente que cuentan para el descuento de bienvenida: los gestionados por Dynamo (no manuales) que no están en borrador ni cancelados. Quién: cualquier usuario con sesión (sin comprobación propia). Argumentos: p_cliente: clientes.id.';
comment on function public.es_admin() is '[Ayudantes internos] Ayudante de permisos: true si quien llama es un usuario de Dynamo activo con rol admin o empleado. Con la clave de servicio da false (no hay usuario). Quién: cualquiera. Argumentos: sin argumentos.';
comment on function public.es_administrador() is '[Ayudantes internos] Ayudante de permisos: true solo si quien llama es el Admin Master (rol admin, cuenta activa). Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.es_dia_habil(p_fecha date, p_pais character, p_region text) is '[Calendario y festivos] Dice si un día es laborable: de lunes a viernes y sin festivo nacional (o de esa región) en el país. No tiene en cuenta festivos locales. Quién: cualquier usuario con sesión. Argumentos: p_fecha: día · p_pais: ISO 2 letras (por defecto ES) · p_region: código de región (opcional).';
comment on function public.es_servidor() is '[Ayudantes internos] Ayudante de permisos: true si la llamada viene con la clave de servicio (service_role) o por conexión directa a la base de datos (sin rol de API). Quién: cualquiera. Argumentos: sin argumentos.';
comment on function public.es_solo_lectura() is '[Ayudantes internos] Ayudante de permisos: true si quien llama es un usuario de Dynamo de solo lectura (admin_lectura o empleado_lectura). Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.euros_txt(p numeric) is '[Ayudantes internos] Formatea un importe en euros al estilo español (1.234,50 €); «—» si es nulo. Para textos de avisos. Quién: cualquiera. Argumentos: p: importe.';
comment on function public.exportar_datos_usuario(p_usuario uuid) is '[Protección de datos] RGPD (derecho de acceso): devuelve en jsonb todo lo que la plataforma guarda de un usuario: cuenta, empresa, fichas de contacto con su email, envíos que creó, firmas de CMR con su email, consultas de precio y tiempo conectado. Solo consulta. Quién: el propio usuario (sus datos) o Dynamo (de cualquiera). Argumentos: p_usuario: usuarios.id (null = el que llama).';
comment on function public.factor_automatico(p_cliente uuid) is '[Precio y pago] Descuento de bienvenida que toca a un cliente: el % del parámetro factor_bienvenida_pct mientras tenga menos envíos que factor_bienvenida_envios; si no, 0. Quién: cualquier usuario con sesión (sin comprobación propia). Argumentos: p_cliente: clientes.id.';
comment on function public.fecha_ddmmyyyy(p date) is '[Ayudantes internos] Formatea una fecha como DD/MM/YYYY (para exportaciones). Quién: cualquiera. Argumentos: p: fecha.';
comment on function public.festivo_cae_en(p_fecha date, p_desde date, p_repetir text, p_dias_pascua smallint, p_hasta date) is '[Ayudantes internos] Ayudante de festivos: dice si un festivo (fecha de inicio, forma de repetirse no/cada_anio/pascua, días desde Pascua y fin de vigencia) cae en un día concreto. Quién: cualquier usuario con sesión. Argumentos: p_fecha: día a comprobar · p_desde: festivos.fecha · p_repetir: no, cada_anio o pascua · p_dias_pascua: desplazamiento respecto al Domingo de Pascua · p_hasta: vigente hasta (opcional).';
comment on function public.festivos_entre(p_desde date, p_hasta date, p_pais character, p_region text) is '[Calendario y festivos] Festivos de un periodo con su fecha real de cada año (resuelve los que se repiten y los de Pascua) para un país y, opcionalmente, una región. Máximo 3 años de periodo. Sin festivos locales. Quién: cualquier usuario con sesión (RLS de festivos). Argumentos: p_desde, p_hasta: periodo · p_pais: ISO 2 letras (por defecto ES) · p_region: código de región (opcional).';
comment on function public.firmar_cmr_publico(p_token uuid, p_parada uuid, p_rol text, p_nombre text, p_documento text, p_pais text, p_validado boolean, p_email text, p_ruta text, p_ip inet, p_navegador text, p_sha256 text) is '[CMR y PIN] Enlace público del CMR: guarda una firma (remitente en una recogida, destinatario en una entrega, transportista una vez sin parada). Exige nombre, documento y que la imagen del trazo ya esté subida en la carpeta de ese enlace. No se puede firmar dos veces la misma casilla ni en envíos cancelados. Devuelve {resultado}. Quién: público con token del CMR. Argumentos: p_token · p_parada: envio_paradas.id (null si es el transportista) · p_rol: remitente, transportista o destinatario · p_nombre, p_documento, p_pais (del documento) · p_validado: documento validado · p_email (opcional) · p_ruta: cmr/<token>/<uuid>.png en el bucket documentos · p_ip, p_navegador · p_sha256: huella del documento (64 hex).';
comment on function public.fn_guardar_km_cp(p_pais_origen character, p_cp_origen text, p_pais_destino character, p_cp_destino text, p_km numeric, p_minutos integer, p_proveedor text) is '[Distancias y cobertura] Guarda en la caché los km (y minutos) entre dos códigos postales que acaba de devolver el servicio de rutas; si ya existe la pareja, la actualiza. Devuelve el id. Las reglas por fila no dejan escribir a usuarios: en la práctica solo el servidor. Quién: servidor (con sesión lo frena RLS). Argumentos: p_pais_origen, p_cp_origen, p_pais_destino, p_cp_destino · p_km · p_minutos (opcional) · p_proveedor (por defecto google_routes).';
comment on function public.fn_guardar_km_lugares(p_origen uuid, p_destino uuid, p_km numeric, p_minutos integer, p_proveedor text) is '[Distancias y cobertura] Guarda en la caché los km entre dos sitios guardados, sellando la versión de su ubicación (si luego se mueve un sitio, la distancia deja de valer). Devuelve el id. Las reglas por fila no dejan escribir a usuarios: en la práctica solo el servidor. Quién: servidor (con sesión lo frena RLS). Argumentos: p_origen, p_destino: lugares.id · p_km · p_minutos (opcional) · p_proveedor (por defecto google_routes).';
comment on function public.fn_km_cp(p_pais_origen character, p_cp_origen text, p_pais_destino character, p_cp_destino text, p_max_edad interval) is '[Distancias y cobertura] Km guardados en la caché entre dos códigos postales (CP normalizados), o null si no hay o son más viejos que la edad máxima. Quién: Dynamo y servidor (RLS: los demás reciben null). Argumentos: p_pais_origen, p_cp_origen, p_pais_destino, p_cp_destino · p_max_edad: antigüedad máxima (por defecto 1 año).';
comment on function public.fn_km_lugares(p_origen uuid, p_destino uuid, p_max_edad interval) is '[Distancias y cobertura] Km guardados en la caché entre dos sitios, solo si ninguno se ha movido desde que se calculó; null si no hay o son demasiado viejos. Quién: Dynamo y servidor (RLS: los demás reciben null). Argumentos: p_origen, p_destino: lugares.id · p_max_edad: antigüedad máxima (por defecto 12 meses).';
comment on function public.fn_restriccion_punto(p_pais character, p_cp text, p_tipo_parada text, p_tipo_carga tipo_carga, p_fecha date) is '[Distancias y cobertura] Reglas que afectan a un punto (país + CP + si es carga o descarga + tipo de carga + fecha): fuera de cobertura y restricciones de servicio activas. Devuelve nombre, efecto (bloquea, solo_admin o aviso) y mensaje, las que bloquean primero. Quién: cualquier usuario con sesión. Argumentos: p_pais: ISO 2 letras · p_cp: código postal · p_tipo_parada: carga o descarga (por defecto descarga) · p_tipo_carga (opcional) · p_fecha (por defecto hoy).';
comment on function public.fn_restricciones_ruta(p_envio uuid) is '[Distancias y cobertura] Todas las restricciones que afectan a un envío, parada por parada (orden, punto, tipo, nombre de la regla, efecto y mensaje). Quién: quien puede ver el envío (RLS). Argumentos: p_envio: envios.id.';
comment on function public.guardar_horario(p_lugar uuid, p_tramos jsonb, p_temporada text) is '[Sitios y horarios] Sustituye entero el horario de un sitio para una temporada (borra los tramos y pone los nuevos). El general no puede quedar vacío. Los tramos de un mismo día no se pueden pisar. Quién: Dynamo o el cliente dueño del sitio (RLS). Argumentos: p_lugar: lugares.id · p_tramos: array jsonb [{dia 1-7 (1 = lunes), abre ''HH:MM'', cierra ''HH:MM''}] · p_temporada: general (por defecto) o verano.';
comment on function public.guardar_horario_verano(p_lugar uuid, p_activo boolean, p_desde text, p_hasta text, p_tramos jsonb) is '[Sitios y horarios] Activa o desactiva el horario de verano de un sitio. Si se activa, exige fechas desde/hasta (MM-DD) y al menos un tramo, y sustituye el horario de verano. Al desactivarlo se guardan las fechas anteriores pero deja de aplicarse. Quién: Dynamo o el cliente dueño del sitio (RLS). Argumentos: p_lugar: lugares.id · p_activo: encender/apagar · p_desde, p_hasta: MM-DD (p. ej. 06-15 y 09-15) · p_tramos: array jsonb [{dia 1-7, abre, cierra}].';
comment on function public.guardar_nota_interna(p_tabla text, p_campo text, p_id uuid, p_texto text) is '[Clientes y cuentas] Guarda (o borra, si el texto va vacío) la nota interna del equipo de Dynamo sobre una ficha. Máx. 5000 caracteres. Estas notas solo las lee Dynamo. Quién: Dynamo (admin o empleado; RLS). Argumentos: p_tabla: usuarios, clientes, transportistas, vehiculos, conductores o almacenamientos · p_campo: anotaciones o incidencias_notas · p_id: id de la ficha · p_texto: la nota (vacío = borrar).';
comment on function public.historial_campos_cliente() is '[Ayudantes internos] Lista fija de campos de un envío cuyos cambios puede ver el cliente en el historial (estado, fechas, mercancía, importe al cliente, matrículas…). Quién: cualquiera. Argumentos: sin argumentos.';
comment on function public.historial_campos_internos(p_tabla text) is '[Ayudantes internos] Campos internos de una tabla que se ocultan al cliente en el historial (hoy solo «anotaciones» de almacenamientos). Quién: cualquiera. Argumentos: p_tabla: nombre de la tabla.';
comment on function public.historial_registro(p_tabla text, p_id uuid) is '[Avisos y panel] Historial de cambios de una ficha (alta, modificaciones con antes/después, borrado), los más recientes primero (máx. 300). Dynamo lo ve todo; el cliente solo de sus fichas y de los campos que puede ver, y sin nombres de Dynamo ni del transportista. Quién: Dynamo (también solo lectura) o cliente dueño de la ficha. Argumentos: p_tabla: envios, incidencias, almacenamientos, lugares u operadores · p_id: id de la ficha.';
comment on function public.hito_visible_fuera(p tipo_hito) is '[Ayudantes internos] Dice si un tipo de hito del envío se enseña fuera de Dynamo (cliente/transportista): creado, confirmado, asignado, matrícula, cargado, entregado, cancelado, CMR firmado, PIN validado, incidencia… Quién: cualquiera. Argumentos: p: tipo de hito.';
comment on function public.holded_operacion(p_pais character) is '[Facturación] Tipo de operación para la facturación según el país: general (España o sin país), intracomunitaria (UE) o exportacion (resto). Quién: cualquiera. Argumentos: p_pais: ISO 2 letras.';
comment on function public.horario_del_dia(p_lugar uuid, p_fecha date) is '[Sitios y horarios] Horario de un sitio un día concreto (el de verano si lo tiene activo y cae en sus fechas). Devuelve los tramos abre/cierra y la temporada usada. Vacío = cerrado o sin horario. Quién: cualquier usuario con acceso al sitio (RLS). Argumentos: p_lugar: lugares.id · p_fecha: día (date).';
comment on function public.horario_sitio_txt(p_lugar uuid, p_fecha date) is '[Sitios y horarios] Horario de un sitio en texto libre para una fecha: el texto de verano (con «(horario de verano)») si aplica, o el general. Quién: cualquier usuario con acceso al sitio (RLS). Argumentos: p_lugar: lugares.id · p_fecha: día (opcional).';
comment on function public.latido() is '[Clientes y cuentas] La web lo llama cada pocos minutos mientras el usuario está conectado: suma 5 minutos de conexión de hoy (como mucho uno cada 4 min). Sirve para las métricas de uso. Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.liberar_reserva(p_reserva uuid, p_motivo text) is '[Ofertas y transportistas] Suelta una reserva de carga viva o pendiente de revisión (la deja liberada con su motivo), deja un hito y caduca las reservas del envío que toque, para que otro transportista pueda cogerla. Devuelve {resultado}. Quién: quien tenga el id de la reserva (anon, sesión o servidor; sin más comprobación). Argumentos: p_reserva: envio_reservas.id · p_motivo: texto (máx. 200).';
comment on function public.mantenimiento_activo() is '[Sistema y tareas automáticas] Dice si la plataforma está en modo mantenimiento (parámetro mantenimiento_activo). Quién: cualquiera (también sin sesión). Argumentos: sin argumentos.';
comment on function public.marcar_avisos_vistos() is '[Avisos y panel] Marca como vistos todos los avisos de la campana del usuario que llama (guarda la hora). Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.marcar_exportados(p_fichero text, p_refs text[], p_quitar boolean) is '[Facturación] Marca (o desmarca) como exportados unos envíos por referencia GX: pedido de venta o de compra a facturación, o publicado en bolsa (se puede volver a publicar si cambió). Devuelve cuántos envíos cambió. Quién: Dynamo (admin o empleado). Argumentos: p_fichero: venta, compra o bolsa · p_refs: array de referencias GX · p_quitar: true = desmarcar.';
comment on function public.marcar_facturados(p_lado text, p_refs text[], p_valor boolean) is '[Facturación] Marca o desmarca como facturados unos envíos por referencia GX, del lado de venta (al cliente) o de compra (del transportista). Devuelve cuántos cambió. Quién: Dynamo (admin o empleado). Argumentos: p_lado: venta o compra · p_refs: array de referencias GX · p_valor: true facturado / false no.';
comment on function public.marcar_mi_envio_manual(p_envio uuid, p_estado text, p_precio numeric) is '[Envíos] El cliente cambia el estado de uno de sus envíos manuales (los que mueve con su propio operador) y, si quiere, el precio acordado con el operador. Al pasar a en ruta o entregado pone la fecha real de carga. No en cancelados ni en envíos de Dynamo. Quién: cliente dueño del envío manual. Argumentos: p_envio: envios.id · p_estado: programado, hacia_la_carga, cargando, en_ruta o entregado · p_precio: precio acordado con el operador, sin IVA (opcional).';
comment on function public.marcar_mi_viaje(p_envio uuid, p_estado text) is '[Envíos] El transportista avanza el estado de su viaje (hacia la carga → cargando → en ruta → entregado). No puede volver atrás. Al pasar a en ruta o entregado pone la fecha real de carga. Quién: transportista del envío. Argumentos: p_envio: envios.id · p_estado: hacia_la_carga, cargando, en_ruta o entregado.';
comment on function public.marcar_pago_envio(p_envio uuid, p_accion text, p_motivo text) is '[Precio y pago] Gestiona el pago previo de un envío: transferencia (marca pagado), exento (con motivo), requerir (pide pago previo; solo si aún no se ha ofertado) o deshacer (vuelve a pendiente; no si se pagó con tarjeta o ya se ofertó). No en envíos manuales. Devuelve {resultado}. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id · p_accion: transferencia, exento, requerir o deshacer · p_motivo: obligatorio para exento (mín. 3), opcional para requerir.';
comment on function public.marcar_pin_enviado(p_parada uuid, p_destino text) is '[CMR y PIN] Apunta que el PIN de una parada se ha enviado (cuándo y a quién) y deja un hito. Error si la parada no tiene PIN. Quién: Dynamo y servidor. Argumentos: p_parada: envio_paradas.id · p_destino: a dónde se envió (email o teléfono, máx. 200).';
comment on function public.marcar_sitio_principal(p_cliente uuid, p_lugar uuid) is '[Sitios y horarios] Estrella de la pantalla Sitios: fija el sitio principal (por defecto) del cliente. Quién: Dynamo o el propio cliente. Argumentos: p_cliente: clientes.id · p_lugar: lugares.id (null = quitar).';
comment on function public.metricas_usuarios() is '[Clientes y cuentas] Métricas de uso por usuario: nº de consultas de precio, minutos conectados de media al día (30 días) y a la semana (4 semanas) y último latido. Quién: Dynamo (también solo lectura). Argumentos: sin argumentos.';
comment on function public.mi_cambio_envio(p_envio uuid) is '[Envíos] Para el cliente: el cambio que ha pedido en un envío (propuesta, estado, fecha y nota de Dynamo), si el envío aún se puede modificar y si ya tiene camión (o pasó el corte de cancelación). Quién: cliente dueño del envío. Argumentos: p_envio: envios.id.';
comment on function public.mi_cobertura_credito() is '[Precio y pago] Estado de crédito del cliente que llama, sin importes: disponible, nulo (sin crédito) o sinclasif (sin clasificar). Quién: cliente. Argumentos: sin argumentos.';
comment on function public.mi_conductor_guardar(p_id uuid, p_nombre text, p_documento text, p_documento_pais character, p_telefono text) is '[Ofertas y transportistas] El transportista da de alta (sin id) o edita (con id) un conductor de su flota. Nombre obligatorio (máx. 120), documento máx. 30. Devuelve el id del conductor. Quién: transportista (cuenta activa). Argumentos: p_id: conductores.id (null = nuevo) · p_nombre: nombre y apellidos · p_documento: DNI/NIE/pasaporte · p_documento_pais: ISO 2 letras (por defecto ES) · p_telefono.';
comment on function public.mi_contraoferta(p_envio uuid) is '[Precio y pago] Para el cliente: si puede contraofertar el precio de un envío (lo tiene permitido y la función está encendida), su propuesta, cuándo la hizo y el precio inicial que le dio Dynamo. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id.';
comment on function public.mi_empresa() is '[Clientes y cuentas] Ficha de la empresa del cliente que llama: código, razón social, nombre comercial, CIF, dirección, plazo de pago, preferencias por defecto (camión, forma de carga, plataforma, discreción comercial) y estado de la cuenta. Quién: cliente. Argumentos: sin argumentos.';
comment on function public.mi_empresa_transportista() is '[Clientes y cuentas] Ficha de la empresa del transportista que llama: código, razón social, CIF, dirección, plazo de pago, NIMA, bolsa y código en la bolsa y datos del seguro CMR. Quién: transportista. Argumentos: sin argumentos.';
comment on function public.mi_enlace_cmr(p_envio uuid) is '[CMR y PIN] Devuelve el token del enlace para firmar el CMR de un envío (crea uno nuevo si no hay vigente, revocando los viejos). No para envíos en borrador o cancelados. Quién: cliente o transportista del envío. Argumentos: p_envio: envios.id.';
comment on function public.mi_flota_baja(p_tipo text, p_id uuid) is '[Ofertas y transportistas] El transportista da de baja (desactiva, no borra) un camión o un conductor de su flota. Quién: transportista (cuenta activa). Argumentos: p_tipo: vehiculo o conductor · p_id: vehiculos.id o conductores.id.';
comment on function public.mi_transporte_guardar(p_nima text, p_seguro_compania text, p_seguro_poliza text, p_seguro_vence date) is '[Ofertas y transportistas] El transportista guarda en su ficha el NIMA (residuos) y los datos de su seguro CMR (compañía, póliza, vencimiento). Los vacíos se borran. Quién: transportista (cuenta activa). Argumentos: p_nima (máx. 40) · p_seguro_compania (máx. 120) · p_seguro_poliza (máx. 60) · p_seguro_vence: fecha de vencimiento.';
comment on function public.mi_valoracion_envio(p_envio uuid) is '[Envíos] Para el cliente: si puede valorar un envío (entregado, de Dynamo y con transportista), la nota y comentario que dio, cuándo, y si aún la puede cambiar (30 días). Quién: cliente dueño del envío. Argumentos: p_envio: envios.id.';
comment on function public.mi_vehiculo_guardar(p_id uuid, p_matricula text, p_tipo tipo_vehiculo, p_itv date, p_seguro date, p_tarjeta date, p_adr boolean, p_trampilla boolean) is '[Ofertas y transportistas] El transportista da de alta (sin id) o edita (con id) un camión de su flota. La matrícula solo se pone al crear y no puede estar ya activa en otra flota; al editar no cambia. Devuelve el id del vehículo. Quién: transportista (cuenta activa). Argumentos: p_id: vehiculos.id (null = nuevo) · p_matricula · p_tipo · p_itv, p_seguro, p_tarjeta: fechas de vencimiento (ITV, seguro, tarjeta de transporte) · p_adr: apto mercancías peligrosas · p_trampilla: tiene plataforma elevadora.';
comment on function public.mis_avisos(p_cliente uuid, p_transportista uuid) is '[Avisos y panel] Avisos de la campana de los últimos 60 días (máx. 30), con si son nuevos desde la última vez que se marcaron vistos. Cliente y transportista ven los suyos; Dynamo ve los de Dynamo o, si pasa un cliente o transportista, los de ese. Quién: cualquier usuario con sesión. Argumentos: p_cliente: clientes.id (solo Dynamo, opcional) · p_transportista: transportistas.id (solo Dynamo, opcional).';
comment on function public.mis_envios() is '[Envíos] Lista de envíos del cliente que llama con lo que puede ver: estados, fechas, mercancía, origen/destino, paradas, importe (oculto mientras la solicitud espera precio), matrículas y conductor (este se oculta pasado un tiempo de la entrega). Más recientes primero. Quién: cliente. Argumentos: sin argumentos.';
comment on function public.mis_ofertas() is '[Ofertas y transportistas] Ofertas de carga activas y sin caducar para el transportista que llama (envío programado y aún sin confirmar): precio ofertado, mínimo y máximo de la banda, pronto pago, caducidad, fechas, medidas y poblaciones, y el token del enlace. Quién: transportista. Argumentos: sin argumentos.';
comment on function public.mis_penalizaciones() is '[Precio y pago] Penalizaciones del cliente que llama (sin las canceladas ni las que no le cobran nada), con su importe al cliente sin IVA, tipo, envío y estado. Quién: cliente. Argumentos: sin argumentos.';
comment on function public.mis_penalizaciones_transportista() is '[Ofertas y transportistas] Penalizaciones del transportista que llama (sin las canceladas ni las que no le afectan), con su importe al transportista sin IVA, tipo, envío y estado. Quién: transportista. Argumentos: sin argumentos.';
comment on function public.mis_viajes() is '[Ofertas y transportistas] Viajes asignados al transportista que llama, con lo que necesita: fechas, mercancía, requisitos de carga, importe al transportista (sin IVA), matrículas, conductor, paradas y origen/destino. Los de carga más reciente primero. Quién: transportista. Argumentos: sin argumentos.';
comment on function public.negociacion_publica(p_token uuid) is '[Ofertas y transportistas] Enlace público de una oferta: dice si el transportista puede proponer otro precio (negociar) para esa carga o la negociación está bloqueada. Quién: público con token de oferta. Argumentos: p_token: token del enlace de la oferta.';
comment on function public.normaliza_cp(p text) is '[Ayudantes internos] Normaliza un código postal para compararlo: quita espacios, guiones y cualquier signo y lo pasa a mayúsculas. Quién: cualquiera. Argumentos: p: código postal.';
comment on function public.normaliza_id_fiscal(p text) is '[Ayudantes internos] Normaliza un CIF/NIF/VAT para comparar: quita guiones, puntos, espacios y signos y lo pasa a mayúsculas. Base de la unicidad de CIF. Quién: cualquiera. Argumentos: p: identificador fiscal.';
comment on function public.normaliza_matricula(p text) is '[Ayudantes internos] Normaliza una matrícula para comparar: solo letras y números, en mayúsculas. Quién: cualquiera. Argumentos: p: matrícula.';
comment on function public.oferta_publica(p_token uuid) is '[Ofertas y transportistas] Enlace público de una oferta de carga: si sigue disponible (o por qué no: cancelada, tomada, caducada), si alguien la tiene reservada ahora, y los datos para decidir: fechas, mercancía, requisitos, precio y banda, pronto pago, minutos de reserva y paradas (solo CP, población y horario, sin direcciones). Quién: público con token de oferta. Argumentos: p_token: token del enlace de la oferta.';
comment on function public.ofertar_envio(p_envio uuid, p_transportista uuid, p_canal text, p_precio numeric, p_banda_pct smallint, p_pronto_pago boolean) is '[Ofertas y transportistas] Crea una oferta de carga para un envío programado y sin transportista confirmado: personal (a un transportista activo) o abierta (sin transportista). Caduca a los días del parámetro oferta_dias_caducidad. Pasa el envío a «ofertada» y deja un hito. Devuelve el id de la oferta. Quién: Dynamo y servidor. Argumentos: p_envio: envios.id · p_transportista: transportistas.id (null = oferta abierta) · p_canal: por dónde se envía (texto, p. ej. email, whatsapp, bolsa) · p_precio: precio al transportista sin IVA · p_banda_pct: margen de negociación en % (por defecto 10) · p_pronto_pago: ofrece pronto pago (por defecto sí, si el transportista lo admite).';
comment on function public.otras_cargas_publicas(p_token uuid) is '[Ofertas y transportistas] Tablón del enlace público: con el token de una carga reciente, lista hasta 12 cargas más publicadas en bolsa, libres y con precio (fechas, medidas, tipo de carga, precio al transportista, CP y población de origen y destino, y su token). Quién: público con token de oferta. Argumentos: p_token: token de un enlace de carga (de los últimos días del parámetro tablon_enlace_dias).';
comment on function public.pago_limite(p_desde timestamp with time zone) is '[Precio y pago] Hora límite para pagar un envío con pago previo: el instante dado más las horas del parámetro previo_pago_horas (24 por defecto). Quién: cualquier usuario con sesión. Argumentos: p_desde: desde cuándo está pendiente el pago.';
comment on function public.pagos_envio(p_envio uuid) is '[Precio y pago] Envíos que requieren pago previo con su situación: estado del pago, motivo, método, cuándo se pagó, base, IVA y total en euros, hora límite para pagar y si el precio es provisional (pendiente de revisión). Dynamo ve todos; el cliente los suyos. Quién: Dynamo (también solo lectura) o cliente. Argumentos: p_envio: envios.id (null = todos los que puede ver).';
comment on function public.pais_nombre(p character) is '[Ayudantes internos] Nombre en español de un país a partir de su código ISO de 2 letras (si no lo conoce, devuelve el código). Quién: cualquiera. Argumentos: p: ISO 2 letras.';
comment on function public.pedir_cambio_envio(p_envio uuid, p_desde date, p_hasta date, p_detalle text) is '[Envíos] El cliente pide cambiar un envío programado. Solo fechas y sin camión: se aplica al momento. Con texto de detalle: queda pendiente de Dynamo. Con camión asignándose o pasada la hora límite de cancelación, no se puede (hay que llamar). Fechas desde mañana y hasta 183 días. Devuelve {resultado}. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id · p_desde, p_hasta: nuevas fechas de carga (opcional) · p_detalle: otros cambios en texto (máx. 1000).';
comment on function public.poner_datos_cmr(p_envio uuid, p_bultos integer, p_embalaje text, p_volumen numeric) is '[CMR y PIN] Guarda los datos del CMR de un envío: nº de bultos, embalaje y volumen. Dynamo, en cualquier envío no cancelado; el cliente, solo antes de cargar y si el CMR no tiene firmas. Quién: Dynamo o cliente dueño del envío. Argumentos: p_envio: envios.id · p_bultos: número de bultos · p_embalaje: tipo de embalaje (texto) · p_volumen: m³.';
comment on function public.precio_por_revisar(p text) is '[Ayudantes internos] Dice si un estado de revisión de precio significa que el precio es provisional (pendiente, revisar o esperando_cliente). Quién: cualquiera. Argumentos: p: envios.precio_revision.';
comment on function public.pronto_pago_descuento(p_importe numeric) is '[Precio y pago] Descuento que se aplica al transportista por cobrar por pronto pago: el % del parámetro pronto_pago_pct sobre el importe, con un mínimo de pronto_pago_minimo (euros). Quién: cualquier usuario con sesión. Argumentos: p_importe: importe del viaje en euros sin IVA.';
comment on function public.pronto_pago_estado() is '[Precio y pago] Situación de la línea de pronto pago a transportistas: línea total, si está encendida, ventana de días, cuánto se ha anticipado, cuánto queda y si se puede ofrecer ahora. Dynamo ve además la lista de anticipos. Quién: cualquier usuario con sesión (la lista, solo Dynamo). Argumentos: sin argumentos.';
comment on function public.proponer_precio_solicitud(p_envio uuid, p_importe numeric, p_importe_transportista numeric) is '[Precio y pago] Dynamo pone precio a una solicitud de envío de un cliente: fija el importe al cliente (y opcionalmente al transportista) y la deja en «precio propuesto» con validez de las horas del parámetro solicitud_validez_horas. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id (solicitud en borrador) · p_importe: precio al cliente sin IVA (> 0) · p_importe_transportista: precio al transportista sin IVA (opcional).';
comment on function public.purgar_datos_personales() is '[Protección de datos] RGPD: limpieza periódica de datos personales viejos (IP y navegador de reservas, intentos fallidos, minutos de conexión, consultas de precio; teléfonos de conductores solo si se activa). Apagada por defecto: sin el parámetro rgpd_limpieza_activa no borra nada. Devuelve cuántos registros tocó. Quién: servidor (tarea automática), consola o Admin Master. Argumentos: sin argumentos.';
comment on function public.regenerar_pin_parada(p_parada uuid) is '[CMR y PIN] Genera un PIN nuevo para una parada (para validar la carga/entrega) y reinicia intentos y bloqueo. No si la parada ya está validada. Devuelve el PIN. Quién: Dynamo y servidor. Argumentos: p_parada: envio_paradas.id.';
comment on function public.registrar_cambio_email(p_usuario uuid, p_antes text, p_despues text) is '[Clientes y cuentas] Apunta en la auditoría un cambio de email de una cuenta ya hecho (comprueba que el usuario ya tiene el email nuevo). No cambia el email, solo lo registra. Quién: solo el Admin Master. Argumentos: p_usuario: usuarios.id · p_antes: email anterior · p_despues: email nuevo.';
comment on function public.reglas_precio_envio() is '[Precio y pago] Reglas de precio para la pantalla de pedir envío (de los parámetros): antelación máxima en días, días con precio cerrado, días hábiles para revisar el precio y margen % de revisión. Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.renumerar_paradas(p_envio uuid) is '[Ayudantes internos] Compacta el orden de las paradas de un envío a 1..n sin huecos. Quién: quien puede editar las paradas (RLS). Argumentos: p_envio: envios.id.';
comment on function public.reservar_envio(p_token uuid, p_ip inet, p_navegador text) is '[Ofertas y transportistas] Enlace público de una carga: al abrirlo, reserva la carga unos minutos (parámetro reserva_minutos) para quien lo abre, si está libre. Si ya está tomada o la tiene otro reservada, lo dice. Cuenta la apertura y deja hitos. Devuelve {resultado: reservada | en_tramite | tomada | enlace_no_valido, reserva_id, hasta}. Quién: público con token de oferta o de carga. Argumentos: p_token: token de la oferta o token público del envío · p_ip: IP de quien abre · p_navegador: navegador (máx. 400).';
comment on function public.reservas_cmr_publico(p_token uuid) is '[CMR y PIN] Enlace público del CMR: reservas u observaciones anotadas en el CMR (quién, en qué parada, texto y cuándo). Quién: público con token del CMR. Argumentos: p_token: token del enlace del CMR.';
comment on function public.resolver_cambio_envio(p_envio uuid, p_aceptar boolean, p_nota text) is '[Envíos] Dynamo acepta o rechaza el cambio pendiente que pidió el cliente en un envío. Si acepta y el cambio trae fechas, las aplica; lo demás del detalle hay que cambiarlo a mano. Guarda la nota para el cliente. Devuelve {resultado: ok | no_pendiente}. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id · p_aceptar: true acepta / false rechaza · p_nota: respuesta para el cliente (opcional).';
comment on function public.resolver_contraoferta(p_reserva uuid, p_aprobar boolean) is '[Ofertas y transportistas] Dynamo aprueba o rechaza la contraoferta de precio (o el alta online) de un transportista que está pendiente de revisión. Si aprueba y la carga sigue libre y programada, se la asigna a ese precio; si rechaza, la carga vuelve a estar ofertada. Devuelve {resultado}. Quién: Dynamo y servidor. Argumentos: p_reserva: envio_reservas.id (pendiente_revision) · p_aprobar: true aprueba / false rechaza.';
comment on function public.resolver_contraoferta_cliente(p_envio uuid, p_aprobar boolean) is '[Precio y pago] Dynamo aprueba o rechaza la contraoferta de precio de un cliente en su solicitud. Si aprueba, el envío queda programado con el precio del cliente (no si la fecha de carga ya pasó); si rechaza, vuelve al precio de Dynamo con validez renovada. Deja un hito. Quién: Dynamo (admin o empleado). Argumentos: p_envio: envios.id (solicitud en contraoferta) · p_aprobar: true aprueba / false rechaza.';
comment on function public.responder_precio_solicitud(p_envio uuid, p_acepta boolean) is '[Precio y pago] El cliente acepta o rechaza el precio que Dynamo propuso a su solicitud. Aceptar: el envío queda programado (si el precio no ha caducado y la fecha no ha pasado). Rechazar: el envío se cancela. Devuelve aceptada, rechazada o caducado. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id (solicitud con precio propuesto) · p_acepta: true acepta / false rechaza.';
comment on function public.responder_subida_precio(p_envio uuid, p_acepta boolean) is '[Precio y pago] Respuesta a una subida de precio tras la revisión antes de la carga. Aceptar: el nuevo precio pasa a ser el definitivo y avisa a Dynamo. No aceptar: el envío se cancela sin coste. Solo si el envío está programado y esperando al cliente. Devuelve {resultado}. Quién: cliente dueño del envío o Dynamo. Argumentos: p_envio: envios.id · p_acepta: true acepta / false cancela.';
comment on function public.revisar_precio_envio(p_envio uuid, p_nuevo numeric) is '[Precio y pago] Fija el precio definitivo de un envío con precio provisional. Si cambia menos del margen (parámetro, 5 %) se mantiene; si baja, se aplica; si sube más del margen, queda esperando que el cliente acepte o cancele sin coste. Avisa al cliente en cada caso. Devuelve {resultado: mantenido | bajado | subida…}. Quién: Dynamo y servidor. Argumentos: p_envio: envios.id (programado con precio por revisar) · p_nuevo: precio al cliente en euros sin IVA.';
comment on function public.revisar_precios_programados() is '[Sistema y tareas automáticas] Tarea diaria: marca «revisar» los envíos cuyo precio provisional toca revisar hoy y avisa a Dynamo; y avisa de los clientes que no han contestado a una subida de precio pasadas las horas del parámetro. Devuelve cuántos avisos generó. Quién: servidor (tarea automática), consola o Dynamo. Argumentos: sin argumentos.';
comment on function public.revision_precio_envio(p_envio uuid) is '[Precio y pago] Datos de la revisión de precio de un envío: cuándo se calculó, estado de la revisión, fecha prevista, precio anterior y nuevo, cuándo se revisó y margen %. Nada mientras la solicitud espera precio. Quién: Dynamo (también solo lectura) o cliente dueño del envío. Argumentos: p_envio: envios.id.';
comment on function public.riesgos_clientes() is '[Clientes y cuentas] Riesgo de crédito por cliente: límite de CESCE y manual, el que manda, envíos sin pago previo de los últimos días (parámetro riesgo_dias_asumido) con su base y total con IVA, crédito disponible y último envío. A quien no es de Dynamo no le devuelve nada. Quién: Dynamo (también solo lectura). Argumentos: sin argumentos.';
comment on function public.sitio_principal(p_cliente uuid) is '[Sitios y horarios] Id del sitio principal (por defecto) de un cliente, o null. Quién: Dynamo o el propio cliente. Argumentos: p_cliente: clientes.id.';
comment on function public.sn(p boolean) is '[Ayudantes internos] Convierte un sí/no en «S» o «N» (para exportaciones). Null da «N». Quién: cualquiera. Argumentos: p: valor booleano.';
comment on function public.transportista_del_usuario() is '[Ayudantes internos] Ayudante de reglas por fila: id del transportista del usuario que llama si es un usuario de transportista con cuenta activa; si no, null. Quién: cualquiera (devuelve null si no es transportista). Argumentos: sin argumentos.';
comment on function public.unaccent_simple(t text) is '[Ayudantes internos] Quita tildes, diéresis, ñ y ç (á→a, ñ→n…) para buscar sin acentos. Quién: cualquiera. Argumentos: t: texto.';
comment on function public.validar_pin_manual(p_parada uuid, p_nota text) is '[CMR y PIN] Dynamo valida a mano el PIN de una parada (p. ej. el conductor no lo tiene o quedó bloqueado). Exige una nota con quién llamó y el motivo (mín. 5 caracteres). Pone la hora real de la parada y deja hito e incidencia. Devuelve {resultado}. Quién: Dynamo y servidor. Argumentos: p_parada: envio_paradas.id · p_nota: explicación (mín. 5 caracteres).';
comment on function public.validar_restricciones_envio(p_envio uuid) is '[Distancias y cobertura] Da error si alguna parada del envío choca con una restricción que bloquea (o que solo Dynamo puede aceptar y quien llama no es Dynamo). Si no hay problema no devuelve nada. Se usa al confirmar envíos. Quién: quien puede ver el envío (RLS). Argumentos: p_envio: envios.id.';
comment on function public.validar_ruta_envio(p_envio uuid) is '[Envíos] Da error si la ruta del envío no es válida: menos de 2 paradas, o la primera no es una carga o la última no es una descarga. Si es válida no devuelve nada. Quién: quien puede ver el envío (RLS). Argumentos: p_envio: envios.id.';
comment on function public.valorar_mi_envio(p_envio uuid, p_nota smallint, p_comentario text) is '[Envíos] El cliente valora de 1 a 5 estrellas (con comentario opcional, máx. 500) un envío entregado de Dynamo. Se puede cambiar durante 30 días. Recalcula la valoración media del transportista. Quién: cliente dueño del envío. Argumentos: p_envio: envios.id · p_nota: 1 a 5 · p_comentario: texto (opcional).';
comment on function public.ve_todo() is '[Ayudantes internos] Ayudante de permisos: true si quien llama es cualquier usuario de Dynamo activo, también los de solo lectura (admin, empleado, admin_lectura, empleado_lectura). Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
comment on function public.verano_sitios_fechas() is '[Sitios y horarios] Fechas por defecto del horario de verano de los sitios (MM-DD, de los parámetros; si no, 05-25 a 09-15), para proponerlas en la pantalla. Quién: cualquier usuario con sesión. Argumentos: sin argumentos.';
